__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"LEVEL_DATA",{enumerable:!0,get:function(){return u}});var t=r(d[0]),n=r(d[1]),_=r(d[2]),o=r(d[3]);const u={words:(0,r(d[4]).withExamples)(o.N2_WORDS,_.N2_EXAMPLES),grammar:t.N2_GRAMMAR,reading:n.N2_READING}},1892,[1908,1909,1910,1911,1899]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"N2_GRAMMAR",{enumerable:!0,get:function(){return n}});const n=[{id:'n2-g01',pattern:'〜以上（は）',connection:'普通形（な形容詞・名詞＋である） ＋ 以上（は）',meaning:'既然〜就〜',example:{ja:'約束した以上は、守らなければならない。',zh:'既然約好了，就必須遵守。',highlight:'約束した以上は'},tip:'「以上（は）」＝「からには」＝「上は」，後接義務、決心或推斷；名詞・な形要用「である」。',quiz:{blank:'以上は',distractors:['ものの','わりに','あげく']}},{id:'n2-g02',pattern:'〜わけにはいかない',connection:'動詞辭書形 ＋ わけにはいかない',meaning:'不能〜（基於道理）',example:{ja:'証拠がない以上、彼を逮捕するわけにはいかない。',zh:'既然沒有證據，就不能逮捕他。',highlight:'逮捕するわけにはいかない'},tip:'基於道理、常識或立場而「不能做」；注意與「わけがない（不可能）」「わけではない（並非）」區別。',quiz:{blank:'わけにはいかない',distractors:['わけがない','わけではない','しかない']}},{id:'n2-g03',pattern:'〜ざるを得ない',connection:'動詞ない形去ない ＋ ざるを得ない（する→せざるを得ない）',meaning:'不得不〜',example:{ja:'証拠がそろった以上、彼を疑わざるを得ない。',zh:'證據都齊了，不得不懷疑他。',highlight:'疑わざるを得ない'},tip:'書面語，表示被迫不得不做；「する」要變「せざるを得ない」是常考陷阱。',quiz:{blank:'ざるを得ない',distractors:['ずにすむ','ずじまいだ','ないでもない']}},{id:'n2-g04',pattern:'〜にもかかわらず',connection:'普通形／名詞 ＋ にもかかわらず',meaning:'儘管〜',example:{ja:'雨にもかかわらず、たくさんの人が集まった。',zh:'儘管下雨，還是聚集了很多人。',highlight:'にもかかわらず'},tip:'「儘管〜卻」表逆接，後項多為意外結果；勿與「にかかわらず（不論）」混淆。',quiz:{blank:'にもかかわらず',distractors:['にかかわらず','をきっかけに','に応じて']}},{id:'n2-g05',pattern:'〜に違いない',connection:'普通形（な形容詞語幹・名詞不加だ） ＋ に違いない',meaning:'一定是〜',example:{ja:'犯人はこの部屋にいたに違いない。',zh:'犯人一定在這個房間待過。',highlight:'いたに違いない'},tip:'說話者依據推斷的強烈確信；書面版為「に相違ない」。名詞、な形直接接，不加「だ」。',quiz:{blank:'に違いない',distractors:['にすぎない','わけがない','おそれがある']}},{id:'n2-g06',pattern:'〜をきっかけに',connection:'名詞 ＋ をきっかけに',meaning:'以〜為契機',example:{ja:'留学をきっかけに、料理を始めた。',zh:'以留學為契機開始學做菜。',highlight:'留学をきっかけに'},tip:'以某偶然事件為開端而開始新行動；較書面的同義表現為「を契機に」。',quiz:{blank:'をきっかけに',distractors:['をめぐって','を問わず','に反して']}},{id:'n2-g07',pattern:'〜一方だ',connection:'動詞辭書形 ＋ 一方だ',meaning:'越來越〜（單向變化）',example:{ja:'事件の謎は深まる一方だ。',zh:'事件的謎團越來越深。',highlight:'深まる一方だ'},tip:'只接表示變化的動詞，多用於負面趨勢；與「ばかりだ」同義，「つつある」則接ます形。',quiz:{blank:'一方だ',distractors:['ところだ','しかない','ことだ']}},{id:'n2-g08',pattern:'〜あげく',connection:'動詞た形／名詞の ＋ あげく',meaning:'〜的結果（最後）',example:{ja:'さんざん迷ったあげく、何も買わなかった。',zh:'猶豫了半天，結果什麼都沒買。',highlight:'迷ったあげく'},tip:'經過長時間或反覆後，最後得到不好的結果；常與「さんざん」「いろいろ」搭配，「すえ」中性。',quiz:{blank:'あげく',distractors:['とたん','かわりに','次第']}},{id:'n2-g09',pattern:'〜からには',connection:'普通形（な形容詞・名詞＋である） ＋ からには',meaning:'既然〜就一定〜',example:{ja:'引き受けたからには、最後までやる。',zh:'既然接下了，就要做到最後。',highlight:'引き受けたからには'},tip:'「既然〜就要〜」後接決心、義務、建議；與「からといって（並不因為〜就）」常被混考。',quiz:{blank:'からには',distractors:['からといって','からして','どころか']}},{id:'n2-g10',pattern:'〜ものの',connection:'普通形 ＋ ものの',meaning:'雖然〜但是〜',example:{ja:'犯人はわかったものの、証拠がない。',zh:'雖然知道犯人是誰，卻沒有證據。',highlight:'わかったものの'},tip:'書面逆接「雖然〜但」，後項常為與預期不符的狀況；類似「とはいうものの」。',quiz:{blank:'ものの',distractors:['からには','以上','ばかりに']}},{id:'n2-g11',pattern:'〜かねない',connection:'動詞ます形 ＋ かねない',meaning:'很可能〜（負面）',example:{ja:'このままでは事故になりかねない。',zh:'再這樣下去很可能會出事。',highlight:'なりかねない'},tip:'「很可能造成壞結果」只用於負面；肯定形「かねない」反而是「有可能」，與「かねる（難以）」相反。',quiz:{blank:'かねない',distractors:['かねる','っこない','得ない']}},{id:'n2-g12',pattern:'〜をめぐって',connection:'名詞 ＋ をめぐって',meaning:'圍繞著〜',example:{ja:'遺産をめぐって、家族が争っている。',zh:'家人圍繞著遺產發生爭執。',highlight:'遺産をめぐって'},tip:'圍繞某議題產生爭論、對立；後項多為「争う・議論する・対立する」等動詞。',quiz:{blank:'をめぐって',distractors:['をこめて','を通じて','を抜きにして']}},{id:'n2-g13',pattern:'〜ことから',connection:'普通形（な形な／である） ＋ ことから',meaning:'由於〜（根據、由來）',example:{ja:'富士山が見えることから、この町は富士見町と呼ばれている。',zh:'因為看得到富士山，這個鎮被稱為富士見町。',highlight:'見えることから'},tip:'表示判斷根據或名稱由來，常見「〜ことから、〜と呼ばれている」句型。',quiz:{blank:'ことから',distractors:['ことに','ことなく','ことだし']}},{id:'n2-g14',pattern:'〜ことに',connection:'動詞た形／い形容詞辭書形／な形容詞語幹＋な ＋ ことに',meaning:'令人〜的是',example:{ja:'驚いたことに、彼女は八十歳だった。',zh:'令人驚訝的是，她已經八十歲了。',highlight:'驚いたことに'},tip:'接感情形容詞或動詞た形，表說話者的感受（令人〜的是）；書面語，後項不能是意志表現。',quiz:{blank:'ことに',distractors:['ことから','ことか','ものの']}},{id:'n2-g15',pattern:'〜に際して',connection:'動詞辭書形／名詞 ＋ に際して',meaning:'在〜之際',example:{ja:'ご利用に際して、注意事項をお読みください。',zh:'使用時請閱讀注意事項。',highlight:'ご利用に際して'},tip:'正式場合的「在〜之際」；與「にあたって」幾乎同義，常見於公告與致詞。',quiz:{blank:'に際して',distractors:['にかけて','に反して','に代わって']}},{id:'n2-g16',pattern:'〜に先立って',connection:'動詞辭書形／名詞 ＋ に先立って',meaning:'在〜之前（預先）',example:{ja:'工事に先立って、住民への説明会が開かれた。',zh:'施工前先舉辦了居民說明會。',highlight:'工事に先立って'},tip:'強調「事前」先做準備，非單純「之前」；常見於典禮、工程、發售等正式場合。',quiz:{blank:'に先立って',distractors:['に反して','に代わって','にわたって']}},{id:'n2-g17',pattern:'〜にわたって',connection:'名詞（期間・範圍） ＋ にわたって',meaning:'歷經〜；遍及〜',example:{ja:'会議は三日間にわたって行われた。',zh:'會議連續舉行了三天。',highlight:'三日間にわたって'},tip:'前接期間、次數或範圍名詞，強調整體規模；「にかけて」則需「〜から〜にかけて」。',quiz:{blank:'にわたって',distractors:['にかけて','に沿って','に応じて']}},{id:'n2-g18',pattern:'〜を通じて',connection:'名詞 ＋ を通じて',meaning:'透過〜；在整個〜期間',example:{ja:'友人を通じて、彼女と知り合った。',zh:'透過朋友認識了她。',highlight:'友人を通じて'},tip:'兩義：透過某媒介（＝を通して）、在整段期間（一年を通じて）；考試常考媒介用法。',quiz:{blank:'を通じて',distractors:['をめぐって','を問わず','をこめて']}},{id:'n2-g19',pattern:'〜をはじめ',connection:'名詞 ＋ をはじめ（として）',meaning:'以〜為首；〜等等',example:{ja:'東京をはじめ、全国の都市で雪が降った。',zh:'以東京為首，全國各城市都下了雪。',highlight:'東京をはじめ'},tip:'舉出代表例再擴及同類，後項常有「など」「全国」「多くの」。',quiz:{blank:'をはじめ',distractors:['をめぐって','を除いて','を問わず']}},{id:'n2-g20',pattern:'〜に応じて',connection:'名詞 ＋ に応じて',meaning:'根據〜；因應〜',example:{ja:'お客様の予算に応じて、プランを提案します。',zh:'會依照客人的預算提案方案。',highlight:'予算に応じて'},tip:'依對象變化而相應調整，常見「予算・能力・要望に応じて」。',quiz:{blank:'に応じて',distractors:['に反して','に代わって','に先立って']}},{id:'n2-g21',pattern:'〜に基づいて',connection:'名詞 ＋ に基づいて',meaning:'根據〜；基於〜',example:{ja:'この映画は実話に基づいて作られた。',zh:'這部電影是根據真實故事拍攝的。',highlight:'実話に基づいて'},tip:'以資料、事實、規定為根據或基礎；與「をもとに」相近，但更偏書面。',quiz:{blank:'に基づいて',distractors:['に反して','に先立って','にこたえて']}},{id:'n2-g22',pattern:'〜に沿って',connection:'名詞 ＋ に沿って',meaning:'沿著〜；按照〜',example:{ja:'川に沿って、桜の木が並んでいる。',zh:'櫻花樹沿著河岸排列著。',highlight:'川に沿って'},tip:'兩義：沿著道路河川；按照方針期待（方針に沿って）。',quiz:{blank:'に沿って',distractors:['に基づいて','に応じて','にわたって']}},{id:'n2-g23',pattern:'〜にかけては',connection:'名詞 ＋ にかけては',meaning:'在〜方面（不輸人）',example:{ja:'料理の腕にかけては、彼の右に出る者はいない。',zh:'說到廚藝，沒有人比得上他。',highlight:'料理の腕にかけては'},tip:'只用於誇讚能力「在〜方面不輸人」，後項常接「右に出る者はいない」「自信がある」。',quiz:{blank:'にかけては',distractors:['にとっては','に対しては','にしては']}},{id:'n2-g24',pattern:'〜わりに',connection:'普通形（な形な・名詞の） ＋ わりに',meaning:'雖然〜但比想像中〜',example:{ja:'この店は値段のわりに量が多い。',zh:'這家店以價格來說份量很多。',highlight:'値段のわりに'},tip:'結果與前項應有程度不相稱，正負面皆可；「くせに」帶責備語氣且主語須為人。',quiz:{blank:'わりに',distractors:['くせに','ばかりか','あげく']}},{id:'n2-g25',pattern:'〜からこそ',connection:'普通形 ＋ からこそ',meaning:'正因為〜才〜',example:{ja:'君のことを思うからこそ、厳しく言うんだ。',zh:'正因為為你著想，才會說得這麼嚴厲。',highlight:'思うからこそ'},tip:'強調理由「正因為〜才」，常與「のだ」呼應；不能用「からこそ」接一般單純原因。',quiz:{blank:'からこそ',distractors:['からといって','ものの','くせに']}},{id:'n2-g26',pattern:'〜どころか',connection:'普通形（な形・名詞去だ） ＋ どころか',meaning:'別說〜，反而〜',example:{ja:'薬を飲んだのに、治るどころか悪くなった。',zh:'吃了藥，別說好轉，反而更嚴重了。',highlight:'治るどころか'},tip:'否定前項並提出相反或程度更甚的事實；「ばかりか」是同方向累加，常被混考。',quiz:{blank:'どころか',distractors:['ばかりか','うえに','ついでに']}},{id:'n2-g27',pattern:'〜ものなら',connection:'動詞可能形／意向形 ＋ ものなら',meaning:'如果能〜的話；要是〜就糟了',example:{ja:'できるものなら、もう一度学生に戻りたい。',zh:'如果可以的話，真想再回到學生時代。',highlight:'できるものなら'},tip:'接可能形表難以實現的願望；接意向形「ようものなら」則表後果嚴重，需區分。',quiz:{blank:'ものなら',distractors:['ものの','ものか','もので']}},{id:'n2-g28',pattern:'〜ものだ（感慨）',connection:'普通形 ＋ ものだ',meaning:'真是〜啊（感慨）',example:{ja:'月日が経つのは早いものだ。',zh:'時光過得真快啊。',highlight:'早いものだ'},tip:'表發自內心的感慨（真是〜啊），常接形容詞；回想用法接動詞た形，勸告用法接辭書形。',quiz:{blank:'ものだ',distractors:['ことだ','はずだ','ところだ']}},{id:'n2-g29',pattern:'〜ないことはない',connection:'動詞ない形／い形容詞くない／な形容詞・名詞でない ＋ ことはない',meaning:'也不是不〜',example:{ja:'辛い料理も食べられないことはない。',zh:'辣的菜也不是不能吃。',highlight:'食べられないことはない'},tip:'雙重否定表「也不是不〜」，語氣消極保留；與「ないわけにはいかない（不能不）」不同。',quiz:{blank:'ないことはない',distractors:['っこない','ずにすむ','ないではいられない']}},{id:'n2-g30',pattern:'〜っこない',connection:'動詞ます形 ＋ っこない',meaning:'絕不可能〜（口語）',example:{ja:'こんな難しい問題、子どもに解けっこない。',zh:'這麼難的題目，小孩根本不可能解開。',highlight:'解けっこない'},tip:'口語，強烈否定可能性「絕不可能」；同義書面語為「わけがない」「はずがない」。',quiz:{blank:'っこない',distractors:['かねない','つつある','がちだ']}},{id:'n2-g31',pattern:'〜がちだ',connection:'動詞ます形／名詞 ＋ がちだ',meaning:'容易〜；常常〜（負面）',example:{ja:'冬は運動不足になりがちだ。',zh:'冬天容易運動不足。',highlight:'なりがちだ'},tip:'表容易出現負面傾向或頻率高；「気味」指輕微的狀態，「がち」重在次數多。',quiz:{blank:'がちだ',distractors:['かねる','っこない','次第だ']}},{id:'n2-g32',pattern:'〜気味',connection:'動詞ます形／名詞 ＋ 気味',meaning:'有點〜的傾向',example:{ja:'最近、ちょっと風邪気味です。',zh:'最近有點感冒的感覺。',highlight:'風邪気味'},tip:'表「稍微有〜的感覺」，多用於身體或負面狀態；「だらけ」「まみれ」表沾滿，意思不同。',quiz:{blank:'気味',distractors:['だらけ','まみれ','ずくめ']}},{id:'n2-g33',pattern:'〜かねる',connection:'動詞ます形 ＋ かねる',meaning:'難以〜；不便〜',example:{ja:'そのご要望にはお応えしかねます。',zh:'恕難以回應您的要求。',highlight:'お応えしかねます'},tip:'「かねる」為客氣地拒絕（難以〜），多用於服務業；「かねない」則是可能發生壞事。',quiz:{blank:'かねます',distractors:['かねません','がちです','つつあります']}},{id:'n2-g34',pattern:'〜得る',connection:'動詞ます形 ＋ 得る（うる／える）',meaning:'有可能〜',example:{ja:'地震はいつでも起こり得る。',zh:'地震隨時都有可能發生。',highlight:'起こり得る'},tip:'「得る」讀「うる／える」，否定只有「えない」；表示事情發生的可能性，不用於能力。',quiz:{blank:'得る',distractors:['かねる','っこない','つつある']}},{id:'n2-g35',pattern:'〜次第',connection:'動詞ます形／名詞 ＋ 次第',meaning:'一〜就立刻〜；全憑〜',example:{ja:'資料が届き次第、ご連絡いたします。',zh:'資料一送到就立刻與您聯絡。',highlight:'届き次第'},tip:'「一〜就立刻」後接說話者意志行為，不能接過去式；名詞＋次第為「取決於」。',quiz:{blank:'次第',distractors:['つつ','かけ','がてら']}},{id:'n2-g36',pattern:'〜上で',connection:'動詞た形／名詞の ＋ 上で',meaning:'在〜之後（再）；在〜方面',example:{ja:'よく考えた上で、決めてください。',zh:'請仔細考慮之後再決定。',highlight:'考えた上で'},tip:'接た形表「先做完前項再做後項」；接名詞の表「在〜方面」，兩義皆常考。',quiz:{blank:'上で',distractors:['あげく','ところで','とたん']}},{id:'n2-g37',pattern:'〜限り',connection:'動詞普通形／名詞の ＋ 限り',meaning:'只要〜；在〜範圍內',example:{ja:'私が知っている限り、彼は一度も遅刻したことがない。',zh:'就我所知，他從沒遲到過。',highlight:'知っている限り'},tip:'「〜限り（では）」表就所知範圍判斷；接ている／ない形則表「只要〜」條件。',quiz:{blank:'限り',distractors:['以上','からには','ものの']}},{id:'n2-g38',pattern:'〜に越したことはない',connection:'普通形（な形・名詞去だ） ＋ に越したことはない',meaning:'最好是〜；〜再好不過',example:{ja:'健康のためには、早く寝るに越したことはない。',zh:'為了健康，早睡是最好的。',highlight:'早く寝るに越したことはない'},tip:'「最好是〜」表常識上的最佳選擇；與「に限る」相近，但「に限る」較主觀。',quiz:{blank:'に越したことはない',distractors:['にすぎない','に相違ない','にもほどがある']}},{id:'n2-g39',pattern:'〜てしょうがない',connection:'動詞て形／い形容詞くて／な形容詞で ＋ しょうがない',meaning:'〜得不得了',example:{ja:'試験の結果が気になってしょうがない。',zh:'非常在意考試結果。',highlight:'気になってしょうがない'},tip:'口語「〜得不得了」，表無法抑制的感情或生理感覺；同義「てたまらない」「てならない」。',quiz:{blank:'しょうがない',distractors:['はいけない','もかまわない','はいられない']}},{id:'n2-g40',pattern:'〜つつある',connection:'動詞ます形 ＋ つつある',meaning:'正在逐漸〜',example:{ja:'この町の人口は減りつつある。',zh:'這個城鎮的人口正逐漸減少。',highlight:'減りつつある'},tip:'書面語「正逐漸〜」，表變化持續進行；只接變化動詞，不用於「食べる」等動作。',quiz:{blank:'つつある',distractors:['かねない','っこない','得る']}},{id:'n2-g41',pattern:'〜にかかわらず',connection:'名詞／動詞辭書形＋ない形（行く行かない）／い形容詞＋否定形 ＋ にかかわらず',meaning:'不論〜；與〜無關',example:{ja:'天候にかかわらず、捜査は予定通り行う。',zh:'不論天候如何，搜查照預定進行。',highlight:'天候にかかわらず'},tip:'前接含對立兩面的詞（天候、男女、有無）或「〜する・しない」；與「にもかかわらず」常混考。',quiz:{blank:'にかかわらず',distractors:['に限って','に先立って','にこたえて']}},{id:'n2-g42',pattern:'〜に限らず',connection:'名詞 ＋ に限らず',meaning:'不只〜；不限於〜',example:{ja:'この手口は都会に限らず、地方でも見られる。',zh:'這種手法不只在都市，地方也看得到。',highlight:'都会に限らず'},tip:'「不只〜」後接「も」擴大範圍；與「に限って（偏偏）」「に限り（僅限）」常混考。',quiz:{blank:'に限らず',distractors:['に限って','に反して','に代わって']}},{id:'n2-g43',pattern:'〜に限って',connection:'名詞 ＋ に限って',meaning:'偏偏〜；唯獨〜（不會）',example:{ja:'急いでいる日に限って、電車が遅れる。',zh:'偏偏在趕時間的日子電車誤點。',highlight:'日に限って'},tip:'偏偏在某時發生壞事，或「唯獨〜不會」表信任；注意與「に限り（僅限）」區別。',quiz:{blank:'に限って',distractors:['に限らず','に先立って','に沿って']}},{id:'n2-g44',pattern:'〜に限り',connection:'名詞 ＋ に限り',meaning:'僅限〜',example:{ja:'先着十名に限り、無料で参加できます。',zh:'僅限前十名可免費參加。',highlight:'先着十名に限り'},tip:'公告、廣告常用的限定條件「僅限〜」；「に限らず」意思相反。',quiz:{blank:'に限り',distractors:['に限らず','をはじめ','にわたって']}},{id:'n2-g45',pattern:'〜に限る',connection:'名詞／動詞辭書形 ＋ に限る',meaning:'〜最好',example:{ja:'疲れたときは、寝るに限る。',zh:'累的時候睡覺最好。',highlight:'寝るに限る'},tip:'說話者主觀認為「〜最好」；客觀常識版是「に越したことはない」。',quiz:{blank:'に限る',distractors:['にすぎない','に違いない','に等しい']}},{id:'n2-g46',pattern:'〜にこたえて',connection:'名詞 ＋ にこたえて',meaning:'回應〜；響應〜',example:{ja:'市民の要望にこたえて、防犯カメラが増設された。',zh:'回應市民的要求，增設了監視器。',highlight:'要望にこたえて'},tip:'回應期待、要求、聲援而行動，前接「要望・期待・声援」等名詞。',quiz:{blank:'にこたえて',distractors:['に反して','に代わって','に限って']}},{id:'n2-g47',pattern:'〜に反して',connection:'名詞 ＋ に反して',meaning:'與〜相反；違反〜',example:{ja:'予想に反して、容疑者にはアリバイがあった。',zh:'與預料相反，嫌犯有不在場證明。',highlight:'予想に反して'},tip:'兩義：與預測期待相反（予想に反して）、違反規定（規則に反して）。',quiz:{blank:'に反して',distractors:['に応じて','に基づいて','にこたえて']}},{id:'n2-g48',pattern:'〜に伴って',connection:'名詞／動詞辭書形 ＋ に伴って',meaning:'伴隨〜；隨著〜',example:{ja:'人口の増加に伴って、犯罪も増えた。',zh:'隨著人口增加，犯罪也增加了。',highlight:'増加に伴って'},tip:'表一方變化連帶引起另一方變化，書面語，多用於大規模變化；同義「につれて」「にしたがって」。',quiz:{blank:'に伴って',distractors:['に反して','に先立って','に代わって']}},{id:'n2-g49',pattern:'〜にしたがって（變化）',connection:'名詞／動詞辭書形 ＋ にしたがって',meaning:'隨著〜',example:{ja:'調査が進むにしたがって、真相が見えてきた。',zh:'隨著調查進展，真相逐漸浮現。',highlight:'進むにしたがって'},tip:'前後都要是變化的事情；「につれて」同義，但「にしたがって」另有「依照」義。',quiz:{blank:'にしたがって',distractors:['に先立って','に限って','に反して']}},{id:'n2-g50',pattern:'〜にしたがって（依照）',connection:'名詞 ＋ にしたがって',meaning:'依照〜',example:{ja:'係員の指示にしたがって、避難してください。',zh:'請依照工作人員的指示避難。',highlight:'指示にしたがって'},tip:'依照指示、規則、命令行動；同義「に沿って」，相反為「に反して」。',quiz:{blank:'にしたがって',distractors:['に反して','に代わって','に限って']}},{id:'n2-g51',pattern:'〜にあたって',connection:'名詞／動詞辭書形 ＋ にあたって',meaning:'在〜之際（正式）',example:{ja:'調査を始めるにあたって、関係者に話を聞いた。',zh:'開始調查之際，先向相關人士問話。',highlight:'始めるにあたって'},tip:'正式場合「在做〜之前、之際」，常用於致詞；與「に際して」幾乎可互換。',quiz:{blank:'にあたって',distractors:['にかけて','に反して','にわたって']}},{id:'n2-g52',pattern:'〜にかけて',connection:'名詞 ＋ から ＋ 名詞 ＋ にかけて',meaning:'從〜到〜（範圍）',example:{ja:'昨夜から今朝にかけて、雪が降り続いた。',zh:'從昨晚到今早雪一直下。',highlight:'今朝にかけて'},tip:'表時間或空間的大概範圍，常與「から」呼應；「まで」則邊界明確。',quiz:{blank:'にかけて',distractors:['に限って','に先立って','に沿って']}},{id:'n2-g53',pattern:'〜に代わって',connection:'名詞 ＋ に代わって',meaning:'代替〜',example:{ja:'入院中の部長に代わって、私が説明します。',zh:'由我代替住院中的部長說明。',highlight:'部長に代わって'},tip:'代替某人做事，或「取代」舊事物（手紙に代わってメール）。',quiz:{blank:'に代わって',distractors:['に反して','に限って','をめぐって']}},{id:'n2-g54',pattern:'〜に対する',connection:'名詞 ＋ に対する ＋ 名詞',meaning:'對〜的',example:{ja:'被害者に対する思いやりが足りない。',zh:'對被害者缺乏體貼。',highlight:'被害者に対する'},tip:'「に対して」的連體形，後接名詞，表感情或行為的對象。',quiz:{blank:'に対する',distractors:['にとっての','に関する','をめぐる']}},{id:'n2-g55',pattern:'〜にほかならない',connection:'名詞 ＋ にほかならない',meaning:'正是〜；無非是〜',example:{ja:'この傷は犯人と争った証拠にほかならない。',zh:'這道傷痕正是與犯人搏鬥的證據。',highlight:'証拠にほかならない'},tip:'斷定「正是〜，不是別的」；與「にすぎない（只不過）」語氣相反，常一起考。',quiz:{blank:'にほかならない',distractors:['に越したことはない','にもほどがある','にかかっている']}},{id:'n2-g56',pattern:'〜にすぎない',connection:'名詞／普通形 ＋ にすぎない',meaning:'只不過是〜',example:{ja:'それは君の推測にすぎない。',zh:'那只不過是你的推測。',highlight:'推測にすぎない'},tip:'表程度輕「只不過是〜」，帶輕視語氣；常與「にほかならない」對照出題。',quiz:{blank:'にすぎない',distractors:['にほかならない','に越したことはない','に値する']}},{id:'n2-g57',pattern:'〜に相違ない',connection:'名詞／普通形 ＋ に相違ない',meaning:'一定是〜（書面）',example:{ja:'犯人は内部の人間に相違ない。',zh:'犯人一定是內部的人。',highlight:'人間に相違ない'},tip:'書面語，與「に違いない」同義，表強烈確信；名詞、な形直接接續。',quiz:{blank:'に相違ない',distractors:['にすぎない','にもほどがある','に値する']}},{id:'n2-g58',pattern:'〜にきまっている',connection:'名詞／普通形 ＋ にきまっている',meaning:'一定是〜；肯定〜',example:{ja:'そんな話、うそにきまっている。',zh:'那種話肯定是騙人的。',highlight:'うそにきまっている'},tip:'口語，主觀斷定「肯定是〜」；比「に違いない」更主觀、更隨意。',quiz:{blank:'にきまっている',distractors:['に越したことはない','に値する','にかかっている']}},{id:'n2-g59',pattern:'〜にしても',connection:'名詞／普通形 ＋ にしても',meaning:'即使〜也',example:{ja:'冗談にしても、言いすぎだ。',zh:'就算是玩笑也太過分了。',highlight:'冗談にしても'},tip:'讓步「即使〜也」，同義「にしろ」「にせよ」；注意與「にしては（以〜來說）」區別。',quiz:{blank:'にしても',distractors:['にとって','に先立って','に限って']}},{id:'n2-g60',pattern:'〜にしろ〜にしろ',connection:'動詞普通形／名詞 ＋ にしろ',meaning:'無論〜還是〜',example:{ja:'行くにしろ行かないにしろ、連絡してください。',zh:'不管去不去都請聯絡。',highlight:'行くにしろ行かないにしろ'},tip:'「AにしろBにしろ」列舉對立兩項表「無論哪種都」；同義「にせよ〜にせよ」。',quiz:{blank:'ないにしろ',distractors:['ないにしては','ないどころか','ないばかりか']}},{id:'n2-g61',pattern:'〜にせよ',connection:'名詞／普通形 ＋ にせよ',meaning:'即使〜；無論〜',example:{ja:'どんな理由があるにせよ、暴力は許されない。',zh:'不管有什麼理由，暴力都不被允許。',highlight:'あるにせよ'},tip:'讓步，常與「どんな・いくら・たとえ」呼應；「にしろ」「にしても」同義，「にせよ」最書面。',quiz:{blank:'にせよ',distractors:['にしては','にかけては','に限って']}},{id:'n2-g62',pattern:'〜につき（理由）',connection:'名詞 ＋ につき',meaning:'因為〜（告示用語）',example:{ja:'工事中につき、立ち入り禁止。',zh:'施工中，禁止進入。',highlight:'工事中につき'},tip:'告示、通知用語表理由，前接名詞；口語不用。注意另有「每〜」的用法。',quiz:{blank:'につき',distractors:['にかけて','に反して','に際して']}},{id:'n2-g63',pattern:'〜につき（每）',connection:'名詞 ＋ につき',meaning:'每〜',example:{ja:'参加費は一人につき千円です。',zh:'參加費每人一千日圓。',highlight:'一人につき'},tip:'表比例分配「每〜」，常見費用、數量；同義「あたり」。',quiz:{blank:'につき',distractors:['にとって','に限らず','に代わって']}},{id:'n2-g64',pattern:'〜につけ',connection:'動詞辭書形 ＋ につけ',meaning:'每當〜就',example:{ja:'この写真を見るにつけ、あの事件を思い出す。',zh:'每看到這張照片就想起那起案件。',highlight:'見るにつけ'},tip:'每當〜就自然產生某種感情，後接「思い出す・感じる」等；慣用「何かにつけ」。',quiz:{blank:'につけ',distractors:['にしろ','に限って','にかけては']}},{id:'n2-g65',pattern:'〜にあたる',connection:'名詞 ＋ にあたる',meaning:'相當於〜',example:{ja:'彼は被害者のいとこにあたる。',zh:'他是被害者的堂表兄弟。',highlight:'いとこにあたる'},tip:'表相當於某關係、日期或數值（親戚關係、換算）；與「に値する（值得）」不同。',quiz:{blank:'にあたる',distractors:['に値する','に限る','に越したことはない']}},{id:'n2-g66',pattern:'〜にしてみれば',connection:'名詞 ＋ にしてみれば',meaning:'在〜看來',example:{ja:'被害者にしてみれば、許せないことだろう。',zh:'在被害者看來，那是無法原諒的吧。',highlight:'被害者にしてみれば'},tip:'站在某人立場推測其心情，多接人物名詞；同義「にしたら」「にすれば」。',quiz:{blank:'にしてみれば',distractors:['にかけては','に限って','に代わって']}},{id:'n2-g67',pattern:'〜にとどまらず',connection:'名詞／普通形 ＋ にとどまらず',meaning:'不僅限於〜',example:{ja:'被害は東京にとどまらず、全国に広がった。',zh:'受害不只東京，擴及全國。',highlight:'東京にとどまらず'},tip:'範圍超出前項，擴大到更廣的領域；同義「に限らず」「だけでなく」。',quiz:{blank:'にとどまらず',distractors:['に限って','に先立って','に反して']}},{id:'n2-g68',pattern:'〜に至るまで',connection:'名詞 ＋ に至るまで',meaning:'甚至到〜；直到〜',example:{ja:'服装から髪型に至るまで、細かく調べた。',zh:'從服裝到髮型都仔細調查了。',highlight:'髪型に至るまで'},tip:'強調範圍廣，甚至延伸到意想不到的細節；常與「から」呼應。',quiz:{blank:'に至るまで',distractors:['に限って','に対して','に先立って']}},{id:'n2-g69',pattern:'〜にかかっている',connection:'名詞 ＋ にかかっている',meaning:'取決於〜',example:{ja:'事件の解決は、彼の証言にかかっている。',zh:'案件的解決取決於他的證詞。',highlight:'証言にかかっている'},tip:'表成敗取決於某因素，前接「努力・証言・天気」等。',quiz:{blank:'にかかっている',distractors:['にすぎない','に値する','に等しい']}},{id:'n2-g70',pattern:'〜に等しい',connection:'名詞／動詞辭書形 ＋ に等しい',meaning:'等於〜',example:{ja:'手がかりはゼロに等しい。',zh:'線索幾乎等於零。',highlight:'ゼロに等しい'},tip:'表實際上幾乎等同於〜，常見「ゼロに等しい」「無いに等しい」。',quiz:{blank:'に等しい',distractors:['に値する','にかかっている','に限る']}},{id:'n2-g71',pattern:'〜に値する',connection:'名詞／動詞辭書形 ＋ に値する',meaning:'值得〜',example:{ja:'彼の推理は称賛に値する。',zh:'他的推理值得稱讚。',highlight:'称賛に値する'},tip:'前接「称賛・注目・尊敬」等名詞或「読む・見る」，表值得；否定為「に値しない」。',quiz:{blank:'に値する',distractors:['に等しい','にすぎない','にかかっている']}},{id:'n2-g72',pattern:'〜にもほどがある',connection:'名詞／普通形 ＋ にもほどがある',meaning:'〜也要有個限度',example:{ja:'冗談にもほどがある。',zh:'開玩笑也要有個限度。',highlight:'冗談にもほどがある'},tip:'責備對方太過分，口語、帶強烈不滿；慣用「冗談にもほどがある」。',quiz:{blank:'にもほどがある',distractors:['にすぎない','に越したことはない','に値する']}},{id:'n2-g73',pattern:'〜にて',connection:'名詞 ＋ にて',meaning:'在〜；以〜（書面）',example:{ja:'説明会は本社の会議室にて行います。',zh:'說明會在總公司的會議室舉行。',highlight:'会議室にて'},tip:'「で」的書面語，用於通知、公告的場所、手段或時間點（これにて終了）。',quiz:{blank:'にて',distractors:['にかけて','にわたって','につき']}},{id:'n2-g74',pattern:'〜を問わず',connection:'名詞 ＋ を問わず',meaning:'不論〜',example:{ja:'この仕事は年齢を問わず応募できる。',zh:'這份工作不論年齡都可應徵。',highlight:'年齢を問わず'},tip:'前接含對立義的名詞（年齡、男女、晝夜）；同義「にかかわらず」「に関係なく」。',quiz:{blank:'を問わず',distractors:['をめぐって','をこめて','を契機に']}},{id:'n2-g75',pattern:'〜をこめて',connection:'名詞 ＋ をこめて',meaning:'滿懷〜；傾注〜',example:{ja:'感謝をこめて、手紙を書いた。',zh:'滿懷感謝寫了信。',highlight:'感謝をこめて'},tip:'把感情灌注其中，前接「愛・感謝・心」；可作「を込めた＋名詞」。',quiz:{blank:'をこめて',distractors:['をめぐって','を問わず','を通じて']}},{id:'n2-g76',pattern:'〜を契機に',connection:'名詞 ＋ を契機に',meaning:'以〜為契機',example:{ja:'この事件を契機に、警備が強化された。',zh:'以這起案件為契機加強了警備。',highlight:'事件を契機に'},tip:'書面語，與「をきっかけに」同義，表轉折點；也作「を契機として」。',quiz:{blank:'を契機に',distractors:['をめぐって','を問わず','を抜きにして']}},{id:'n2-g77',pattern:'〜を抜きにして',connection:'名詞 ＋ を抜きにして',meaning:'撇開〜；不考慮〜',example:{ja:'動機を抜きにして、この事件は語れない。',zh:'撇開動機就無法談這起案件。',highlight:'動機を抜きにして'},tip:'常以「〜を抜きにしては〜ない」表少了某要素就無法成立。',quiz:{blank:'を抜きにして',distractors:['を契機に','をこめて','を控えて']}},{id:'n2-g78',pattern:'〜を除いて',connection:'名詞 ＋ を除いて',meaning:'除了〜之外',example:{ja:'一人を除いて、全員にアリバイがある。',zh:'除了一人之外，全員都有不在場證明。',highlight:'一人を除いて'},tip:'「除了〜以外」，書面語；口語用「以外」，正式用「を除き」。',quiz:{blank:'を除いて',distractors:['をはじめ','を問わず','をこめて']}},{id:'n2-g79',pattern:'〜を前提に',connection:'名詞 ＋ を前提に',meaning:'以〜為前提',example:{ja:'結婚を前提に、交際している。',zh:'以結婚為前提交往中。',highlight:'結婚を前提に'},tip:'以某條件為前提，常見「結婚を前提に付き合う」；也作「を前提として」。',quiz:{blank:'を前提に',distractors:['を契機に','をめぐって','を問わず']}},{id:'n2-g80',pattern:'〜を頼りに',connection:'名詞 ＋ を頼りに',meaning:'依靠〜；憑著〜',example:{ja:'古い地図を頼りに、山小屋を探した。',zh:'憑著舊地圖尋找山屋。',highlight:'地図を頼りに'},tip:'依靠地圖、記憶、光線等線索行動；也作「を頼りにして」。',quiz:{blank:'を頼りに',distractors:['をこめて','を契機に','を控えて']}},{id:'n2-g81',pattern:'〜を境に',connection:'名詞 ＋ を境に',meaning:'以〜為分界',example:{ja:'あの日を境に、彼は変わってしまった。',zh:'以那天為分界，他變了。',highlight:'あの日を境に'},tip:'以某時間點為分界，前後狀態明顯改變；常接「あの日・事件」。',quiz:{blank:'を境に',distractors:['を前提に','をこめて','を頼りに']}},{id:'n2-g82',pattern:'〜を控えて',connection:'名詞 ＋ を控えて',meaning:'〜在即',example:{ja:'裁判を控えて、弁護士は忙しそうだ。',zh:'審判在即，律師看起來很忙。',highlight:'裁判を控えて'},tip:'重要事情即將到來，前接考試、婚禮、選舉等；也可用於空間（海を控えた町）。',quiz:{blank:'を控えて',distractors:['を前提に','を問わず','をこめて']}},{id:'n2-g83',pattern:'〜を踏まえて',connection:'名詞 ＋ を踏まえて',meaning:'根據〜；考慮〜',example:{ja:'調査結果を踏まえて、方針を決める。',zh:'根據調查結果決定方針。',highlight:'調査結果を踏まえて'},tip:'以前提、結果為基礎進一步思考決策，書面語，常接「結果・経験・意見」。',quiz:{blank:'を踏まえて',distractors:['を控えて','をこめて','を境に']}},{id:'n2-g84',pattern:'〜を受けて',connection:'名詞 ＋ を受けて',meaning:'接到〜；受〜影響',example:{ja:'通報を受けて、警察が駆けつけた。',zh:'接到通報，警察趕到了。',highlight:'通報を受けて'},tip:'接收到通報、指示、結果後，以此為基礎而採取行動。',quiz:{blank:'を受けて',distractors:['を控えて','を境に','を前提に']}},{id:'n2-g85',pattern:'〜を兼ねて',connection:'名詞 ＋ を兼ねて',meaning:'兼作〜',example:{ja:'下見を兼ねて、そのホテルに泊まった。',zh:'兼作勘查，住進了那家飯店。',highlight:'下見を兼ねて'},tip:'一個行動同時兼具兩個目的；也作「〜と〜を兼ねて」。',quiz:{blank:'を兼ねて',distractors:['を控えて','を前提に','を頼りに']}},{id:'n2-g86',pattern:'〜ものがある',connection:'動詞辭書形／形容詞 ＋ ものがある',meaning:'確實有〜之處（感嘆）',example:{ja:'彼の推理には驚くべきものがある。',zh:'他的推理確實有令人驚嘆之處。',highlight:'驚くべきものがある'},tip:'對某特質發出感嘆「確實有〜之處」；常接「すごい・驚くべき・感じる」。',quiz:{blank:'ものがある',distractors:['ものか','ことか','ことにする']}},{id:'n2-g87',pattern:'〜ものか',connection:'普通形 ＋ ものか',meaning:'才不〜（強烈否定）',example:{ja:'あんな男に負けるものか。',zh:'才不會輸給那種男人。',highlight:'負けるものか'},tip:'強烈否定「才不〜」，口語多說「もんか」；女性亦用「ものですか」。',quiz:{blank:'ものか',distractors:['ものだ','もので','ことか']}},{id:'n2-g88',pattern:'〜もので',connection:'普通形 ＋ もので',meaning:'因為〜（客氣的辯解）',example:{ja:'慣れないもので、ご迷惑をおかけしました。',zh:'因為還不熟悉，給您添麻煩了。',highlight:'慣れないもので'},tip:'說明理由並帶辯解、道歉語氣；口語「もんで」，不用於命令、意志句。',quiz:{blank:'もので',distractors:['ものの','ものなら','ものか']}},{id:'n2-g89',pattern:'〜もの（辯解）',connection:'普通形 ＋ もの',meaning:'因為〜嘛（口語）',example:{ja:'だって、本当に知らなかったんだもの。',zh:'因為我真的不知道嘛。',highlight:'知らなかったんだもの'},tip:'口語撒嬌式辯解，常與「だって」呼應，多為女性或孩子使用；也作「もん」。',quiz:{blank:'もの',distractors:['こと','わけ','ところ']}},{id:'n2-g90',pattern:'〜ものだ（當然）',connection:'動詞辭書形 ＋ ものだ',meaning:'本來就應該〜（常理）',example:{ja:'人の話は最後まで聞くものだ。',zh:'別人說話本來就該聽到最後。',highlight:'聞くものだ'},tip:'表社會常理「本來就應該〜」；與「ことだ（給個人的忠告）」常被混考。',quiz:{blank:'ものだ',distractors:['わけだ','ところだ','一方だ']}},{id:'n2-g91',pattern:'〜ものだ（回想）',connection:'動詞た形 ＋ ものだ',meaning:'以前常常〜（回憶）',example:{ja:'子どものころ、よくこの公園で遊んだものだ。',zh:'小時候常在這座公園玩。',highlight:'遊んだものだ'},tip:'接動詞た形，常與「よく」「昔は」呼應表懷念的回憶；與表感慨、常理的「ものだ」區分。',quiz:{blank:'ものだ',distractors:['ことだ','わけだ','ところだ']}},{id:'n2-g92',pattern:'〜たいものだ',connection:'動詞ます形 ＋ たいものだ',meaning:'真想〜啊',example:{ja:'一度でいいから、本物の名探偵に会いたいものだ。',zh:'哪怕一次也好，真想見見真正的名偵探。',highlight:'会いたいものだ'},tip:'「たいものだ」強調強烈願望；否定願望為「〜ないものか」。',quiz:{blank:'ものだ',distractors:['ことだ','ものか','はずだ']}},{id:'n2-g93',pattern:'〜たものではない',connection:'動詞可能形た形 ＋ ものではない',meaning:'根本不能〜',example:{ja:'こんな料理、食べられたものではない。',zh:'這種料理根本沒法吃。',highlight:'食べられたものではない'},tip:'接可能形た形，強烈否定「根本無法〜」，帶批評語氣；口語「たもんじゃない」。',quiz:{blank:'たものではない',distractors:['ないことはない','たものだ','がちだ']}},{id:'n2-g94',pattern:'〜ないものか',connection:'動詞ない形 ＋ ものか',meaning:'難道不能〜嗎（願望）',example:{ja:'何とか彼を救えないものか。',zh:'難道不能想辦法救他嗎？',highlight:'救えないものか'},tip:'接可能形ない形，表強烈希望「難道不能〜嗎」；與單純否定的「ものか」不同。',quiz:{blank:'ものか',distractors:['ものだ','もので','ことに']}},{id:'n2-g95',pattern:'〜ようものなら',connection:'動詞意向形 ＋ ものなら',meaning:'要是〜的話（後果嚴重）',example:{ja:'彼に逆らおうものなら、ただでは済まない。',zh:'要是違抗他，可不會善了。',highlight:'逆らおうものなら'},tip:'接意向形，表一旦做了就會導致嚴重後果；與接可能形的「ものなら（如果能）」區分。',quiz:{blank:'ものなら',distractors:['ものの','もので','ところで']}},{id:'n2-g96',pattern:'〜ものと思われる',connection:'普通形 ＋ ものと思われる',meaning:'據判斷〜（書面）',example:{ja:'犯人は裏口から侵入したものと思われる。',zh:'據判斷犯人是從後門侵入的。',highlight:'侵入したものと思われる'},tip:'新聞、報告常用的客觀推測「據判斷〜」，書面語。',quiz:{blank:'ものと思われる',distractors:['ものではない','ものがある','ものか']}},{id:'n2-g97',pattern:'〜というものだ',connection:'名詞／普通形 ＋ というものだ',meaning:'這才是〜；這就叫〜',example:{ja:'困っている人を助けるのが、友情というものだ。',zh:'幫助有困難的人，這才叫友情。',highlight:'友情というものだ'},tip:'表說話者斷言「這才是〜」的本質；否定形「というものではない」意思為並非。',quiz:{blank:'というものだ',distractors:['というものではない','に越したことはない','どころではない']}},{id:'n2-g98',pattern:'〜というものではない',connection:'普通形 ＋ というものではない',meaning:'並非〜就好',example:{ja:'高ければいいというものではない。',zh:'並不是貴就好。',highlight:'いいというものではない'},tip:'表部分否定「並不是〜就好」，常接「ば〜いい」；與「わけではない」相近。',quiz:{blank:'というものではない',distractors:['というものだ','に違いない','わけにはいかない']}},{id:'n2-g99',pattern:'〜とはいうものの',connection:'名詞／普通形 ＋ とはいうものの',meaning:'雖說〜但是',example:{ja:'夏とはいうものの、朝晩は涼しい。',zh:'雖說是夏天，早晚還是很涼。',highlight:'夏とはいうものの'},tip:'承認前項但後項與預期不符「雖說〜」，書面語；同義「とはいえ」。',quiz:{blank:'とはいうものの',distractors:['というより','とすれば','としたら']}},{id:'n2-g100',pattern:'〜ことか',connection:'疑問詞 ＋ 普通形 ＋ ことか',meaning:'多麼〜啊',example:{ja:'無事だと聞いて、どれほど安心したことか。',zh:'聽到平安無事，我是多麼安心啊。',highlight:'どれほど安心したことか'},tip:'常與「どんなに・どれほど・何度」呼應表強烈感慨；與否定的「ものか」不同。',quiz:{blank:'ことか',distractors:['ことに','ことだ','わけだ']}},{id:'n2-g101',pattern:'〜のことだから',connection:'名詞 ＋ の ＋ ことだから',meaning:'因為是〜（所以一定）',example:{ja:'慎重な彼のことだから、証拠を残すはずがない。',zh:'以他謹慎的個性，不可能留下證據。',highlight:'彼のことだから'},tip:'根據對某人性格習慣的了解作判斷，前接人物名詞；後項多為推測。',quiz:{blank:'のことだから',distractors:['のくせに','のわりに','のおかげで']}},{id:'n2-g102',pattern:'〜ことなく',connection:'動詞辭書形 ＋ ことなく',meaning:'不〜而；沒有〜',example:{ja:'犯人は誰にも見られることなく、建物を出た。',zh:'犯人沒被任何人看到就離開了建築物。',highlight:'見られることなく'},tip:'書面語，等於「ないで」「ずに」，表「沒有〜就〜」；常見「休むことなく」。',quiz:{blank:'ことなく',distractors:['ことから','ことに','ことだし']}},{id:'n2-g103',pattern:'〜ないことには',connection:'動詞ない形 ＋ ことには',meaning:'不〜的話就（無法）',example:{ja:'現場を見ないことには、何とも言えない。',zh:'不看現場的話，什麼都無法斷言。',highlight:'見ないことには'},tip:'「ないことには〜ない」表不做前項就無法實現後項；後項必為否定。',quiz:{blank:'ことには',distractors:['ことから','ことなく','ことか']}},{id:'n2-g104',pattern:'〜ことだし',connection:'普通形 ＋ ことだし',meaning:'因為〜（輕微理由）',example:{ja:'雨も止んだことだし、そろそろ出かけようか。',zh:'雨也停了，差不多該出門了吧。',highlight:'止んだことだし'},tip:'口語，舉出一個理由暗示還有其他，後項多為建議或意志「〜しようか」。',quiz:{blank:'ことだし',distractors:['ことから','ことには','ことか']}},{id:'n2-g105',pattern:'〜こととなる',connection:'動詞辭書形 ＋ こととなる',meaning:'將會〜；決定〜（正式）',example:{ja:'来月から、新しい署長が着任することとなった。',zh:'下個月起將由新署長就任。',highlight:'着任することとなった'},tip:'「ことになる」的書面正式版，表非個人意志的決定；「ことにする」為自己決定。',quiz:{blank:'こととなった',distractors:['ことはなかった','ことか','ことなく']}},{id:'n2-g106',pattern:'〜わけでもない',connection:'普通形 ＋ わけでもない',meaning:'也並非〜',example:{ja:'嫌いなわけでもないが、あまり会いたくない。',zh:'也不是討厭，只是不太想見。',highlight:'嫌いなわけでもない'},tip:'部分否定「也並非〜」，比「わけではない」多了「也」的語感。',quiz:{blank:'わけでもない',distractors:['わけがない','わけにはいかない','どころではない']}},{id:'n2-g107',pattern:'〜ないわけにはいかない',connection:'動詞ない形 ＋ わけにはいかない',meaning:'不能不〜',example:{ja:'上司の命令だから、行かないわけにはいかない。',zh:'是上司的命令，不能不去。',highlight:'行かないわけにはいかない'},tip:'基於義務、人情而「不能不做」；與「ざるを得ない」相近，但更偏道理或社會壓力。',quiz:{blank:'ないわけにはいかない',distractors:['ないことはない','ないわけではない','ずにすむ']}},{id:'n2-g108',pattern:'〜ところを',connection:'動詞普通形／い形容詞／な形容詞な／名詞の ＋ ところを',meaning:'正當〜的時候（卻）',example:{ja:'お忙しいところを、ありがとうございます。',zh:'百忙之中，非常感謝您。',highlight:'お忙しいところを'},tip:'多用於道謝、道歉慣用語「お忙しいところを」；也表正在〜時被發現（ところを見られた）。',quiz:{blank:'ところを',distractors:['ところで','ところに','どころか']}},{id:'n2-g109',pattern:'〜たところ',connection:'動詞た形 ＋ ところ',meaning:'〜之後（結果發現）',example:{ja:'調べたところ、指紋は一致しなかった。',zh:'調查之後，發現指紋不吻合。',highlight:'調べたところ'},tip:'做了某事後得到意外結果或發現，後項為過去式；與「たところで（即使〜也）」常被混考。',quiz:{blank:'たところ',distractors:['たきり','たうえで','たばかりに']}},{id:'n2-g110',pattern:'〜どころではない',connection:'名詞／動詞辭書形 ＋ どころではない',meaning:'根本不是〜的時候',example:{ja:'事件が続いて、旅行どころではない。',zh:'案件接連發生，根本顧不上旅行。',highlight:'旅行どころではない'},tip:'因某狀況而根本沒有心思或餘裕做〜；與「どころか（別說〜反而）」形近易混。',quiz:{blank:'どころではない',distractors:['どころか','にすぎない','ばかりではない']}},{id:'n2-g111',pattern:'〜ところによると',connection:'動詞普通形 ＋ ところによると',meaning:'根據〜所說',example:{ja:'聞いたところによると、彼は海外に逃げたらしい。',zh:'據說他好像逃到國外了。',highlight:'聞いたところによると'},tip:'表消息來源，句尾常與「そうだ・らしい」呼應；同義「によると」。',quiz:{blank:'ところによると',distractors:['ところを','ところで','ばかりに']}},{id:'n2-g112',pattern:'〜ない限り',connection:'動詞ない形 ＋ 限り',meaning:'只要不〜就（不）',example:{ja:'本人が自白しない限り、真相はわからない。',zh:'只要本人不自白，真相就不得而知。',highlight:'自白しない限り'},tip:'「〜ない限り」後項多為否定或困難的結果。易與「〜ないことには」（不〜就無法）混淆，兩者語感接近。',quiz:{blank:'限り',distractors:['うちに','ものの','ばかりか']}},{id:'n2-g113',pattern:'〜かぎりでは',connection:'動詞辭書形／た形／ている形・名詞の ＋ かぎりでは',meaning:'就〜所知（所見、所聞）的範圍來說',example:{ja:'私が知るかぎりでは、彼は無実だ。',zh:'就我所知，他是無辜的。',highlight:'知るかぎりでは'},tip:'多接「知る・見る・聞く・調べる」等認知動詞，表示資訊範圍，常見「私の知る限りでは」。',quiz:{blank:'かぎりでは',distractors:['ばかりでは','ものでは','わりには']}},{id:'n2-g114',pattern:'〜とすれば',connection:'普通形 ＋ とすれば',meaning:'假如〜的話',example:{ja:'彼が犯人だとすれば、動機は何だろう。',zh:'假如他是犯人，動機會是什麼？',highlight:'犯人だとすれば'},tip:'假定某前提為真再推論，後項常接推測或疑問。「〜とすれば」與「〜とすると」幾乎可互換。',quiz:{blank:'とすれば',distractors:['とはいえ','にしては','どころか']}},{id:'n2-g115',pattern:'〜とすると',connection:'普通形 ＋ とすると',meaning:'如果〜的話（推論）',example:{ja:'この時計が正しいとすると、犯行は九時だ。',zh:'如果這支錶是準的，犯案時間就是九點。',highlight:'正しいとすると'},tip:'以前項為前提進行推論，後項為判斷。「としても」是讓步（即使〜也），勿混淆。',quiz:{blank:'とすると',distractors:['としても','とはいえ','どころか']}},{id:'n2-g116',pattern:'〜次第だ',connection:'名詞 ＋ 次第だ',meaning:'取決於〜',example:{ja:'成功するかどうかは、君の努力次第だ。',zh:'成不成功取決於你的努力。',highlight:'努力次第だ'},tip:'「名詞＋次第だ」表示取決於〜。另有「動詞ます形＋次第」（一〜就馬上）用法，注意區分。',quiz:{blank:'次第だ',distractors:['ばかりだ','までだ','ものだ']}},{id:'n2-g117',pattern:'〜次第では',connection:'名詞 ＋ 次第では',meaning:'視〜而定，也可能',example:{ja:'証言次第では、彼は無罪になるかもしれない。',zh:'視證詞而定，他也可能無罪。',highlight:'証言次第では'},tip:'「次第では」後項常為可能發生的結果，常與「〜こともある」「〜かもしれない」搭配。',quiz:{blank:'次第では',distractors:['にかけては','にしては','に反して']}},{id:'n2-g118',pattern:'〜となると',connection:'名詞／普通形 ＋ となると',meaning:'如果是〜的話；一旦〜',example:{ja:'犯人が身内となると、話は別だ。',zh:'如果犯人是自家人，那就另當別論了。',highlight:'身内となると'},tip:'表示「如果真是那樣（的情況）」，後項多為說話者的判斷或態度轉變，與「となれば」「となったら」相近。',quiz:{blank:'となると',distractors:['ときたら','にしては','とともに']}},{id:'n2-g119',pattern:'〜ようなら',connection:'動詞・い形容詞普通形／な形容詞な／名詞の ＋ ようなら',meaning:'如果〜的話',example:{ja:'熱が下がらないようなら、病院へ行ってください。',zh:'如果燒不退，請去醫院。',highlight:'下がらないようなら'},tip:'後項常為建議、指示（〜てください）。「ようでは」則接負面評價，是常見混淆點。',quiz:{blank:'ようなら',distractors:['ようでは','ように','ようにも']}},{id:'n2-g120',pattern:'〜ようでは',connection:'動詞・い形容詞普通形／な形容詞な／名詞の ＋ ようでは',meaning:'如果〜那樣的話（負面）',example:{ja:'こんな簡単なトリックに気づかないようでは、探偵失格だ。',zh:'連這麼簡單的詭計都沒發現，就不配當偵探。',highlight:'気づかないようでは'},tip:'後項必為負面評價（〜だめだ、〜失格だ）。與「ようなら」（後接建議）常一起出題比較。',quiz:{blank:'ようでは',distractors:['ようが','ように','ようにも']}},{id:'n2-g121',pattern:'〜てこそ',connection:'動詞て形 ＋ こそ',meaning:'只有〜才（能）',example:{ja:'自分で調べてこそ、本当の答えがわかる。',zh:'只有親自調查，才能知道真正的答案。',highlight:'調べてこそ'},tip:'「〜てこそ」強調只有做了前項，後項才有意義或成立，後項多為正面評價。',quiz:{blank:'てこそ',distractors:['てでも','てまで','ても']}},{id:'n2-g122',pattern:'〜からすると',connection:'名詞 ＋ からすると',meaning:'從〜來看',example:{ja:'足跡の大きさからすると、犯人は男性だろう。',zh:'從腳印大小看來，犯人應是男性。',highlight:'大きさからすると'},tip:'以前項為依據做判斷，後項多為推測（〜だろう）。與「からして」「から見ると」意思相近。',quiz:{blank:'からすると',distractors:['からには','からといって','からこそ']}},{id:'n2-g123',pattern:'〜からいうと',connection:'名詞 ＋ からいうと',meaning:'從〜來說',example:{ja:'経験からいうと、この手の事件は長引く。',zh:'從經驗來說，這類案件會拖很久。',highlight:'経験からいうと'},tip:'表示從某立場或觀點判斷。前接人物時多用「〜からすると」，「からいうと」較少直接接人。',quiz:{blank:'からいうと',distractors:['からには','からといって','からこそ']}},{id:'n2-g124',pattern:'〜からして',connection:'名詞 ＋ からして',meaning:'光從〜就；從〜來看',example:{ja:'名前からして、怪しい会社だ。',zh:'光看名字就知道是家可疑的公司。',highlight:'名前からして'},tip:'「〜からして」舉出一個最基本的例子，暗示其他更不用說，多用於負面評價。',quiz:{blank:'からして',distractors:['からには','からといって','からこそ']}},{id:'n2-g125',pattern:'〜からなる',connection:'名詞 ＋ からなる',meaning:'由〜構成',example:{ja:'捜査班は五人の刑事からなる。',zh:'搜查班由五名刑警組成。',highlight:'刑事からなる'},tip:'表示構成要素，屬書面語。常見「〜からなる委員会」，也可說「〜から成り立つ」。',quiz:{blank:'からなる',distractors:['にわたる','にともなう','をめぐる']}},{id:'n2-g126',pattern:'〜ながらも',connection:'動詞ます形／い形容詞辭書形／な形容詞語幹／名詞 ＋ ながらも',meaning:'雖然〜卻',example:{ja:'狭いながらも、楽しい我が家だ。',zh:'雖然狹小，卻是快樂的家。',highlight:'狭いながらも'},tip:'逆接「雖然〜卻」，前後主語相同。比「のに」書面且不帶不滿語氣，與「つつも」相近。',quiz:{blank:'ながらも',distractors:['あまり','ばかりに','どころか']}},{id:'n2-g127',pattern:'〜つつも',connection:'動詞ます形 ＋ つつも',meaning:'雖然〜卻',example:{ja:'悪いと知りつつも、うそをついてしまった。',zh:'雖然知道不對，還是說了謊。',highlight:'知りつつも'},tip:'「〜つつも」為書面逆接，常見「悪いと知りつつも」「〜と思いつつも」等固定說法。',quiz:{blank:'つつも',distractors:['がてら','ついでに','次第']}},{id:'n2-g128',pattern:'〜つつ（同時）',connection:'動詞ます形 ＋ つつ',meaning:'一邊〜一邊',example:{ja:'景色を楽しみつつ、山道を歩いた。',zh:'一邊欣賞景色一邊走山路。',highlight:'楽しみつつ'},tip:'「〜つつ」表同時進行，比「ながら」書面。加「も」變成逆接，考試常比較兩者。',quiz:{blank:'つつ',distractors:['次第','かけ','きり']}},{id:'n2-g129',pattern:'〜とはいえ',connection:'普通形（名詞・な形容詞的「だ」可省略）＋ とはいえ',meaning:'雖然〜但',example:{ja:'春とはいえ、夜はまだ寒い。',zh:'雖說是春天，晚上還是很冷。',highlight:'春とはいえ'},tip:'承認前項事實但後項與預期相反，書面語。名詞、な形容詞的「だ」常省略。',quiz:{blank:'とはいえ',distractors:['とすれば','となると','ときたら']}},{id:'n2-g130',pattern:'〜というのに',connection:'普通形 ＋ というのに',meaning:'明明〜卻',example:{ja:'もう夜中だというのに、隣の部屋はうるさい。',zh:'都已經半夜了，隔壁還是很吵。',highlight:'夜中だというのに'},tip:'表示「明明〜卻」帶有意外、不滿語氣，常接時間或季節。近義「〜のに」。',quiz:{blank:'というのに',distractors:['というより','というと','からには']}},{id:'n2-g131',pattern:'〜一方で',connection:'動詞・い形容詞普通形／な形容詞な・である／名詞である ＋ 一方で',meaning:'另一方面〜',example:{ja:'彼は優しい一方で、厳しい面もある。',zh:'他很溫柔，另一方面也有嚴厲的一面。',highlight:'優しい一方で'},tip:'對比同一事物的兩面，或並列兩件事。與「一方だ」（越來越〜）形似意異。',quiz:{blank:'一方で',distractors:['あまり','ばかりに','せいで']}},{id:'n2-g132',pattern:'〜かと思うと',connection:'動詞た形 ＋ かと思うと',meaning:'剛〜就（馬上）',example:{ja:'泣いたかと思うと、もう笑っている。',zh:'剛哭完就已經在笑了。',highlight:'泣いたかと思うと'},tip:'表示前項剛發生後項立刻出現，多描述意外變化，不能用於說話者自身的行為。',quiz:{blank:'かと思うと',distractors:['ばかりに','きり','うえで']}},{id:'n2-g133',pattern:'〜か〜ないかのうちに',connection:'動詞辭書形／た形 ＋ か ＋ 同一動詞ない形 ＋ かのうちに',meaning:'剛一〜就',example:{ja:'ベルが鳴るか鳴らないかのうちに、彼は教室を飛び出した。',zh:'鈴聲剛響，他就衝出了教室。',highlight:'鳴るか鳴らないかのうちに'},tip:'前後須為同一動詞，表示幾乎同時發生。後項不可接意志、命令。',quiz:{blank:'かのうちに',distractors:['かのように','かどうか','ばかりに']}},{id:'n2-g134',pattern:'〜上は',connection:'動詞辭書形／た形 ＋ 上は',meaning:'既然〜就',example:{ja:'引き受けた上は、最後までやるしかない。',zh:'既然接下了，就只能做到最後。',highlight:'引き受けた上は'},tip:'「〜上は」＝「〜以上は」，後項多為決心、義務（〜しかない、〜べきだ）。書面語。',quiz:{blank:'上は',distractors:['うちは','きり','わりに']}},{id:'n2-g135',pattern:'〜上（方面）',connection:'名詞 ＋ 上',meaning:'在〜上；從〜方面來看',example:{ja:'法律上、彼を罰することはできない。',zh:'在法律上無法懲罰他。',highlight:'法律上'},tip:'「名詞＋上」表示從某方面來看，如「法律上」「健康上」「教育上」，讀「じょう」。',quiz:{blank:'上',distractors:['的','風','並み']}},{id:'n2-g136',pattern:'〜うえに',connection:'動詞・い形容詞普通形／な形容詞な／名詞の・である ＋ うえに',meaning:'不僅〜而且',example:{ja:'この店は安いうえに、おいしい。',zh:'這家店不但便宜還好吃。',highlight:'安いうえに'},tip:'前後須同為正面或同為負面的累加。與「ばかりか」「だけでなく」意思相近。',quiz:{blank:'うえに',distractors:['くせに','あまり','ばかりに']}},{id:'n2-g137',pattern:'〜あまり',connection:'名詞の／動詞辭書形・た形／な形容詞な ＋ あまり',meaning:'太過〜以致',example:{ja:'緊張のあまり、声が出なかった。',zh:'太過緊張，發不出聲音。',highlight:'緊張のあまり'},tip:'表示程度過度導致不好結果，後項多為非意志性。常見「心配のあまり」「緊張のあまり」。',quiz:{blank:'あまり',distractors:['末に','くせに','わりに']}},{id:'n2-g138',pattern:'〜末に',connection:'名詞の／動詞た形 ＋ 末に',meaning:'經過〜最後',example:{ja:'長い議論の末に、ようやく結論が出た。',zh:'經過長時間討論，終於有了結論。',highlight:'議論の末に'},tip:'經過長時間或反覆嘗試後得到結果。「あげく」多指負面結果，「末に」中性，常一起出題。',quiz:{blank:'末に',distractors:['あまり','くせに','わりに']}},{id:'n2-g139',pattern:'〜きり',connection:'動詞た形 ＋ きり',meaning:'〜之後就再也沒',example:{ja:'彼は家を出たきり、帰ってこない。',zh:'他出門之後就再也沒回來。',highlight:'出たきり'},tip:'「た形＋きり」後接否定，表示之後再也沒發生預期的事。與「〜たまま」意思相近。',quiz:{blank:'きり',distractors:['ばかり','とたん','うえ']}},{id:'n2-g140',pattern:'〜っぱなし',connection:'動詞ます形 ＋ っぱなし',meaning:'一直〜（放著不管）',example:{ja:'現場の窓は開けっぱなしになっていた。',zh:'現場的窗戶一直開著沒關。',highlight:'開けっぱなし'},tip:'表示做了之後放著不管，帶負面語氣。也可表持續狀態，如「立ちっぱなし」。',quiz:{blank:'っぱなし',distractors:['かけ','きり','がち']}},{id:'n2-g141',pattern:'〜かけ',connection:'動詞ます形 ＋ かけ',meaning:'〜到一半',example:{ja:'テーブルに飲みかけのコーヒーが残っていた。',zh:'桌上留著喝到一半的咖啡。',highlight:'飲みかけ'},tip:'表示動作進行到一半，常以「〜かけの＋名詞」修飾名詞，如「読みかけの本」。',quiz:{blank:'かけ',distractors:['っぱなし','きり','がち']}},{id:'n2-g142',pattern:'〜きる',connection:'動詞ます形 ＋ きる',meaning:'〜完；完全〜',example:{ja:'一晩で長編小説を読みきった。',zh:'一個晚上就把長篇小說讀完了。',highlight:'読みきった'},tip:'表示完全做完或達到極限。否定形「〜きれない」表示無法完全做到，常一起考。',quiz:{blank:'きった',distractors:['かけた','そびれた','がたかった']}},{id:'n2-g143',pattern:'〜ても〜きれない',connection:'動詞て形 ＋ も ＋ 動詞ます形 ＋ きれない',meaning:'再怎麼〜也〜不完',example:{ja:'あの日のことは、悔やんでも悔やみきれない。',zh:'那天的事，再怎麼後悔也後悔不完。',highlight:'悔やんでも悔やみきれない'},tip:'前後同一動詞，強調程度之深，屬慣用表現，常見「悔やんでも悔やみきれない」。',quiz:{blank:'きれない',distractors:['かねない','がたい','得ない']}},{id:'n2-g144',pattern:'〜ぬく',connection:'動詞ます形 ＋ ぬく',meaning:'〜到底',example:{ja:'彼は最後まで走りぬいた。',zh:'他堅持跑到了最後。',highlight:'走りぬいた'},tip:'強調克服困難堅持到最後，比「〜きる」更重「忍耐」。常見「やりぬく」「生きぬく」。',quiz:{blank:'ぬいた',distractors:['かけた','そびれた','かねた']}},{id:'n2-g145',pattern:'〜得ない',connection:'動詞ます形 ＋ 得ない',meaning:'不可能〜',example:{ja:'密室から人が消えるなんて、あり得ない。',zh:'人從密室中消失，這不可能。',highlight:'あり得ない'},tip:'「あり得ない」讀「ありえない」，其他動詞多讀「うる／えない」。「〜かねない」表示有可能，意思相反。',quiz:{blank:'得ない',distractors:['かねない','がちだ','かけだ']}},{id:'n2-g146',pattern:'〜がたい',connection:'動詞ます形 ＋ がたい',meaning:'難以〜',example:{ja:'彼の話はにわかには信じがたい。',zh:'他的話令人難以立刻相信。',highlight:'信じがたい'},tip:'表示心理上難以做到，多接「信じる・理解する・許す」等。「〜にくい」偏物理、客觀的難度。',quiz:{blank:'がたい',distractors:['かねない','っぽい','がちだ']}},{id:'n2-g147',pattern:'〜づらい',connection:'動詞ます形 ＋ づらい',meaning:'不方便〜；難以〜',example:{ja:'このメモは字が小さくて読みづらい。',zh:'這張便條字很小，很難讀。',highlight:'読みづらい'},tip:'表示因身心負擔而難做，口語常用。「がたい」偏心理上不可能，「にくい」偏客觀難度。',quiz:{blank:'づらい',distractors:['かねない','っぽい','がちだ']}},{id:'n2-g148',pattern:'〜かのように',connection:'普通形（名詞・な形容詞用「である」）＋ かのように',meaning:'彷彿〜一樣',example:{ja:'彼は何も知らないかのように振る舞った。',zh:'他表現得好像什麼都不知道。',highlight:'知らないかのように'},tip:'表示實際並非如此卻像是那樣。名詞、な形容詞接「である」，如「事実であるかのように」。',quiz:{blank:'かのように',distractors:['ばかりに','どころか','ものの']}},{id:'n2-g149',pattern:'〜まい（意志）',connection:'動詞辭書形 ＋ まい（II類動詞也可接ます形；する→するまい／すまい）',meaning:'絕不〜',example:{ja:'二度と同じ失敗はするまい。',zh:'絕不再犯同樣的失敗。',highlight:'するまい'},tip:'第一人稱的否定意志，書面語。する可作「するまい／すまい」，II類動詞可接ます形。',quiz:{blank:'まい',distractors:['べき','かねない','がちだ']}},{id:'n2-g150',pattern:'〜まい（推量）',connection:'動詞辭書形 ＋ まい（II類動詞也可接ます形；来る→来るまい／来まい）',meaning:'大概不會〜',example:{ja:'この嵐では、彼も来るまい。',zh:'這種暴風雨，他大概不會來。',highlight:'来るまい'},tip:'否定推量＝「〜ないだろう」，書面語。主語多為第三人稱，與意志用法要靠上下文判斷。',quiz:{blank:'まい',distractors:['べきだ','ものだ','ことだ']}},{id:'n2-g151',pattern:'〜まいとする',connection:'動詞辭書形 ＋ まいとする',meaning:'努力不〜',example:{ja:'彼は涙を見せまいとして、顔をそむけた。',zh:'他為了不讓人看到眼淚而別過臉。',highlight:'見せまいとして'},tip:'表示努力不讓某事發生，是「〜ようとする」的否定版，常見「〜まいと（して）」。',quiz:{blank:'まいとして',distractors:['ようとして','かねて','ないとして']}},{id:'n2-g152',pattern:'〜ようか〜まいか',connection:'動詞意向形 ＋ か ＋ 動詞辭書形 ＋ まいか',meaning:'要不要〜（猶豫）',example:{ja:'警察に話そうか話すまいか、迷っている。',zh:'猶豫要不要告訴警察。',highlight:'話そうか話すまいか'},tip:'前後同一動詞，表示猶豫要不要做，後面常接「迷う」「悩む」。',quiz:{blank:'まいか',distractors:['ものか','べきか','ことか']}},{id:'n2-g153',pattern:'〜ようがない',connection:'動詞ます形 ＋ ようがない',meaning:'無法〜；無從〜',example:{ja:'手がかりがなくて、調べようがない。',zh:'沒有線索，無從調查。',highlight:'調べようがない'},tip:'表示沒有方法可做，接ます形。「〜ようもない」語氣更強。與「〜わけがない」意思不同。',quiz:{blank:'ようがない',distractors:['かねない','がちだ','ずにはいられない']}},{id:'n2-g154',pattern:'〜ようにも〜ない',connection:'動詞意向形 ＋ にも ＋ 動詞可能形否定',meaning:'想〜也無法',example:{ja:'雨がひどくて、出かけようにも出かけられない。',zh:'雨太大，想出門也出不去。',highlight:'出かけようにも出かけられない'},tip:'前用意向形、後用同一動詞的可能否定，表示想做卻因故做不到。',quiz:{blank:'にも',distractors:['ものの','ものなら','ので']}},{id:'n2-g155',pattern:'〜ようによっては',connection:'動詞ます形 ＋ ようによっては',meaning:'看〜方式而定',example:{ja:'考えようによっては、これは好機だ。',zh:'換個角度想，這是個好機會。',highlight:'考えようによっては'},tip:'表示換個角度看就有不同評價，常見「考えようによっては」「見ようによっては」。',quiz:{blank:'ようによっては',distractors:['ようがなく','ようにも','ようなら']}},{id:'n2-g156',pattern:'〜ほかない',connection:'動詞辭書形 ＋ ほかない',meaning:'只好〜',example:{ja:'証拠がない以上、釈放するほかない。',zh:'既然沒有證據，只好釋放。',highlight:'釈放するほかない'},tip:'表示別無選擇只好做，與「しかない」「よりほかない」同義，帶無奈語氣。',quiz:{blank:'ほかない',distractors:['わけがない','はずがない','までもない']}},{id:'n2-g157',pattern:'〜より仕方がない',connection:'動詞辭書形 ＋ より仕方がない',meaning:'只能〜',example:{ja:'ここまで来たら、待つより仕方がない。',zh:'到這地步，只能等了。',highlight:'待つより仕方がない'},tip:'同「〜ほかない」「〜しかない」，表示沒有其他辦法。也常說「よりほかない」。',quiz:{blank:'より仕方がない',distractors:['ことはない','わけがない','はずがない']}},{id:'n2-g158',pattern:'〜ずにはいられない',connection:'動詞ない形去ない ＋ ずにはいられない（する→せずにはいられない）',meaning:'不禁〜；忍不住〜',example:{ja:'その話を聞いて、笑わずにはいられなかった。',zh:'聽了那件事，忍不住笑了。',highlight:'笑わずにはいられなかった'},tip:'表示無法克制自然湧現的情緒或行為。「〜ないではいられない」同義；「する」變「せずには」。',quiz:{blank:'ずにはいられなかった',distractors:['ずにすんだ','ずじまいだった','かねなかった']}},{id:'n2-g159',pattern:'〜てならない',connection:'動詞て形／い形容詞くて／な形容詞で ＋ ならない',meaning:'〜得不得了',example:{ja:'あの男の態度が気になってならない。',zh:'非常在意那男人的態度。',highlight:'気になってならない'},tip:'多接情緒、感覺詞（気になる・心配だ・残念だ），表示不由自主。近義「〜てたまらない」。',quiz:{blank:'てならない',distractors:['てはいけない','てもかまわない','てはいられない']}},{id:'n2-g160',pattern:'〜までだ',connection:'動詞辭書形 ＋ までだ',meaning:'大不了就〜',example:{ja:'だめなら、別の方法を試すまでだ。',zh:'不行的話，試別的方法就是了。',highlight:'試すまでだ'},tip:'「辭書形＋までだ」表示大不了就這麼做；「た形＋までだ」表示只是〜而已，兩用法常被考。',quiz:{blank:'までだ',distractors:['ばかりだ','わけがない','どころではない']}},{id:'n2-g161',pattern:'〜までして',connection:'名詞 ＋ までして',meaning:'甚至不惜〜',example:{ja:'借金までして、彼は何を買ったのか。',zh:'他甚至不惜借錢，到底買了什麼？',highlight:'借金までして'},tip:'表示為達目的不惜做到極端的事，帶說話者驚訝或批判。接名詞，動詞用「〜てまで」。',quiz:{blank:'までして',distractors:['ばかりして','もかまわず','はともかく']}},{id:'n2-g162',pattern:'〜てまで',connection:'動詞て形 ＋ まで',meaning:'甚至到〜的地步',example:{ja:'うそをついてまで、彼をかばうのか。',zh:'甚至說謊也要袒護他嗎？',highlight:'うそをついてまで'},tip:'表示不惜採取極端手段，後項多帶批判或疑問。「〜てでも」則強調說話者決心。',quiz:{blank:'てまで',distractors:['ても','てこそ','てばかり']}},{id:'n2-g163',pattern:'〜てでも',connection:'動詞て形 ＋ でも',meaning:'即使〜也要',example:{ja:'どんな手を使ってでも、真相を暴いてみせる。',zh:'不管用什麼手段，我都要揭露真相。',highlight:'使ってでも'},tip:'表示即使採取極端手段也要達成，後項多為意志、願望。常與「どんな手を使って」搭配。',quiz:{blank:'てでも',distractors:['てこそ','てばかり','てから']}},{id:'n2-g164',pattern:'〜だけあって',connection:'名詞／動詞・い形容詞普通形／な形容詞な ＋ だけあって',meaning:'不愧是〜',example:{ja:'ベテラン刑事だけあって、観察が鋭い。',zh:'不愧是資深刑警，觀察力敏銳。',highlight:'刑事だけあって'},tip:'表示與身分、努力相符的正面評價，常與「さすが」搭配。「だけに」可正可負，範圍較廣。',quiz:{blank:'だけあって',distractors:['くせに','ばかりか','どころか']}},{id:'n2-g165',pattern:'〜だけに',connection:'名詞／動詞・い形容詞普通形／な形容詞な ＋ だけに',meaning:'正因為〜更加',example:{ja:'期待していただけに、失望も大きい。',zh:'正因為期待過，失望也更大。',highlight:'期待していただけに'},tip:'「正因為〜所以更加〜」，結果可正可負。與「だけあって」（只用於正面評價）常一起考。',quiz:{blank:'だけに',distractors:['くせに','ばかりか','ものの']}},{id:'n2-g166',pattern:'〜だけの',connection:'動詞辭書形 ＋ だけの ＋ 名詞',meaning:'足夠〜的',example:{ja:'彼には家族を養うだけの収入がない。',zh:'他沒有足夠養家的收入。',highlight:'養うだけの'},tip:'「〜だけの＋名詞」表示足以〜的程度或數量，常見「〜だけの力／お金がない」。',quiz:{blank:'だけの',distractors:['ばかりの','きりの','うえの']}},{id:'n2-g167',pattern:'〜だけのことはある',connection:'名詞／動詞・い形容詞普通形／な形容詞な ＋ だけのことはある',meaning:'不愧是〜',example:{ja:'さすが名探偵と呼ばれるだけのことはある。',zh:'不愧被稱為名偵探。',highlight:'呼ばれるだけのことはある'},tip:'常與「さすが」搭配，表示名不虛傳，屬事後評價；「だけあって」後面還要接評價內容。',quiz:{blank:'だけのことはある',distractors:['わけではない','にすぎない','どころではない']}},{id:'n2-g168',pattern:'〜だけましだ',connection:'普通形 ＋ だけましだ',meaning:'〜已經算好了',example:{ja:'けががなかっただけましだ。',zh:'沒受傷就算好了。',highlight:'なかっただけましだ'},tip:'表示雖然情況不好，但比起更糟的情況還算好。常見「〜だけまだましだ」。',quiz:{blank:'だけましだ',distractors:['ばかりだ','どころではない','わけがない']}},{id:'n2-g169',pattern:'〜ばかりか',connection:'動詞・い形容詞普通形／な形容詞な／名詞 ＋ ばかりか',meaning:'不只〜甚至',example:{ja:'彼は謝らないばかりか、文句まで言った。',zh:'他不只不道歉，甚至還抱怨。',highlight:'謝らないばかりか'},tip:'後項常與「も・まで・さえ」呼應，程度遞進。與「ばかりに」（只因為）只差一字常被考。',quiz:{blank:'ばかりか',distractors:['ばかりに','ものの','とたんに']}},{id:'n2-g170',pattern:'〜ばかりに',connection:'動詞・い形容詞普通形／な形容詞な／名詞である ＋ ばかりに',meaning:'只因為〜（導致壞結果）',example:{ja:'うそをついたばかりに、疑われてしまった。',zh:'只因說了謊，就被懷疑了。',highlight:'ついたばかりに'},tip:'表示只因某原因導致不好的結果，帶後悔語氣。「〜たいばかりに」則表示為了〜不惜。',quiz:{blank:'ばかりに',distractors:['ばかりか','とたん','くせに']}},{id:'n2-g171',pattern:'〜ばかりだ（變化）',connection:'動詞辭書形 ＋ ばかりだ',meaning:'一直〜（越來越糟）',example:{ja:'事件の謎は深まるばかりだ。',zh:'案件之謎越來越深。',highlight:'深まるばかりだ'},tip:'表示持續朝壞的方向變化，前接變化動詞。與「〜一方だ」同義，但「一方だ」可用於好壞兩面。',quiz:{blank:'ばかりだ',distractors:['までだ','次第だ','ものだ']}},{id:'n2-g172',pattern:'〜のみならず',connection:'名詞／普通形 ＋ のみならず',meaning:'不僅〜（書面）',example:{ja:'この事件は国内のみならず、海外でも報道された。',zh:'這起事件不僅國內，海外也有報導。',highlight:'国内のみならず'},tip:'「不僅〜而且」的書面語，後項常有「も」呼應，同「だけでなく」「ばかりでなく」。',quiz:{blank:'のみならず',distractors:['はともかく','にかわって','に限って']}},{id:'n2-g173',pattern:'〜はもとより',connection:'名詞 ＋ はもとより',meaning:'〜自不待言（正式）',example:{ja:'警察はもとより、市民も捜索に協力した。',zh:'警察自不必說，市民也協助了搜索。',highlight:'警察はもとより'},tip:'前項為理所當然者，後項常用「も」。比「はもちろん」更正式。',quiz:{blank:'はもとより',distractors:['はともかく','にかわって','に反して']}},{id:'n2-g174',pattern:'〜もかまわず',connection:'名詞 ＋ もかまわず',meaning:'不顧〜',example:{ja:'彼は人目もかまわず、泣き出した。',zh:'他不顧旁人眼光哭了起來。',highlight:'人目もかまわず'},tip:'表示不顧周遭眼光或後果，常見「人目もかまわず」「なりふりかまわず」，多帶負面評價。',quiz:{blank:'もかまわず',distractors:['はともかく','をめぐって','にこたえて']}},{id:'n2-g175',pattern:'〜はともかく',connection:'名詞 ＋ はともかく',meaning:'〜暫且不論',example:{ja:'見た目はともかく、味はいい。',zh:'外觀暫且不論，味道很好。',highlight:'見た目はともかく'},tip:'表示暫且不談前項，重點在後項。與「はさておき」「は別として」接近；「はもとより」意思相反。',quiz:{blank:'はともかく',distractors:['はもとより','のみならず','ばかりか']}},{id:'n2-g176',pattern:'〜はさておき',connection:'名詞 ＋ はさておき',meaning:'先不管〜',example:{ja:'冗談はさておき、本題に入ろう。',zh:'玩笑先擺一邊，進入正題吧。',highlight:'冗談はさておき'},tip:'表示先擱置前項、轉入正題，常見「冗談はさておき」「それはさておき」。',quiz:{blank:'はさておき',distractors:['はもとより','のみならず','ばかりか']}},{id:'n2-g177',pattern:'〜は別として',connection:'名詞 ＋ は別として',meaning:'〜另當別論',example:{ja:'動機は別として、手口は単純だ。',zh:'動機另當別論，手法很單純。',highlight:'動機は別として'},tip:'表示把前項排除在考量外，也作「は別にして」。常與「〜かどうかは別として」搭配。',quiz:{blank:'は別として',distractors:['はもとより','のみならず','にもまして']}},{id:'n2-g178',pattern:'〜ならともかく',connection:'名詞 ＋ ならともかく',meaning:'如果是〜還說得過去',example:{ja:'子どもならともかく、大人がそんなことをするとは。',zh:'如果是小孩還說得過去，大人竟然做那種事。',highlight:'子どもならともかく'},tip:'表示前項還情有可原，後項則不行，後項多帶批評語氣。與「はともかく」用法不同。',quiz:{blank:'ならともかく',distractors:['ならでは','にしては','だけあって']}},{id:'n2-g179',pattern:'〜はいうまでもない',connection:'普通形（な形容詞な／名詞な・である）＋ の ＋ は言うまでもない；名詞 ＋ は言うまでもない',meaning:'〜不用說',example:{ja:'証拠が大切なのは、いうまでもない。',zh:'證據很重要，這不用說。',highlight:'いうまでもない'},tip:'表示理所當然不必說。常作「〜は言うまでもなく、〜も」；「〜までもない」也可接其他動詞。',quiz:{blank:'までもない',distractors:['わけがない','ほどでもない','ものではない']}},{id:'n2-g180',pattern:'〜といったら',connection:'名詞 ＋ といったら',meaning:'說到〜（感嘆）',example:{ja:'その時の驚きといったら、言葉にならなかった。',zh:'說到那時的驚訝，簡直無法形容。',highlight:'驚きといったら'},tip:'表示程度極端到難以形容，後項常為「〜ない」或感嘆。與話題提示「〜といえば」不同。',quiz:{blank:'といったら',distractors:['といっても','にしては','ばかりか']}},{id:'n2-g181',pattern:'〜とのことだ',connection:'普通形 ＋ とのことだ',meaning:'據說〜（轉達）',example:{ja:'部長は少し遅れるとのことです。',zh:'部長說會晚一點到。',highlight:'遅れるとのことです'},tip:'轉達聽來的消息，比「〜そうだ」正式，常用於商務場合傳話。',quiz:{blank:'とのことです',distractors:['ものです','わけがありません','ところです']}},{id:'n2-g182',pattern:'〜のではないだろうか',connection:'普通形（な形容詞な／名詞な）＋ のではないだろうか',meaning:'是不是〜呢（委婉主張）',example:{ja:'犯人は最初から近くにいたのではないだろうか。',zh:'犯人是不是一開始就在附近呢？',highlight:'いたのではないだろうか'},tip:'委婉表達自己的意見或推測，書面論說文常用。比「〜と思う」語氣更保留。',quiz:{blank:'のではないだろうか',distractors:['わけがない','ものか','にすぎない']}},{id:'n2-g183',pattern:'〜ではないか',connection:'動詞・い形容詞普通形／な形容詞語幹／名詞 ＋ ではないか',meaning:'不是〜嗎（強調、發現）',example:{ja:'これこそ探していた証拠ではないか。',zh:'這不正是我們在找的證據嗎！',highlight:'証拠ではないか'},tip:'語調下降表示驚訝、發現或責備；語調上升則為確認。名詞、な形容詞直接接續。',quiz:{blank:'ではないか',distractors:['とは限らない','どころではない','にすぎない']}},{id:'n2-g184',pattern:'〜ようではないか',connection:'動詞意向形 ＋ ではないか',meaning:'讓我們〜吧（號召）',example:{ja:'みんなで力を合わせて、犯人を捜そうではないか。',zh:'大家同心協力找出犯人吧！',highlight:'捜そうではないか'},tip:'意向形＋ではないか是演講、號召常用的書面表現，口語為「〜ようじゃないか」。',quiz:{blank:'ではないか',distractors:['ものか','としている','とはしない']}},{id:'n2-g185',pattern:'〜とみられる',connection:'普通形 ＋ とみられる',meaning:'被認為〜；據推測〜',example:{ja:'火事の原因は放火とみられる。',zh:'火災原因據推測是縱火。',highlight:'放火とみられる'},tip:'新聞報導常用的客觀推測表現。「とみられている」表示一般看法，與「とされる」相近。',quiz:{blank:'とみられる',distractors:['どころではない','ほかない','ばかりだ']}},{id:'n2-g186',pattern:'〜とされる',connection:'普通形 ＋ とされる',meaning:'被視為〜',example:{ja:'この絵は本物とされている。',zh:'這幅畫被視為真品。',highlight:'本物とされている'},tip:'表示一般被認定、公認的說法，屬書面語，常見於報導或論文。',quiz:{blank:'とされている',distractors:['どころではない','ほかない','とは限らない']}},{id:'n2-g187',pattern:'〜とみえる',connection:'普通形 ＋ とみえる',meaning:'看來〜',example:{ja:'よほど急いでいたとみえて、財布を忘れていった。',zh:'看來非常著急，連錢包都忘了帶走。',highlight:'急いでいたとみえて'},tip:'根據觀察到的情況推測，常以「よほど〜とみえて」出現，多用於第三人稱。',quiz:{blank:'とみえて',distractors:['とはいえ','としても','にしては']}},{id:'n2-g188',pattern:'〜のも無理はない',connection:'普通形 ＋ のも無理はない',meaning:'也難怪〜',example:{ja:'あれだけ働けば、疲れるのも無理はない。',zh:'那樣工作，難怪會累。',highlight:'疲れるのも無理はない'},tip:'表示在某情況下理所當然，同「〜のも当然だ」，前項常有「〜ば」「〜から」說明原因。',quiz:{blank:'のも無理はない',distractors:['わけがない','ことはない','どころではない']}},{id:'n2-g189',pattern:'〜ずにすむ',connection:'動詞ない形去ない ＋ ずにすむ（する→せずにすむ）',meaning:'不必〜就解決了',example:{ja:'友人が手伝ってくれたので、徹夜せずにすんだ。',zh:'朋友幫了忙，所以不用熬夜。',highlight:'徹夜せずにすんだ'},tip:'表示原本可能要做的事不必做了，帶慶幸語氣。「する」變「せずにすむ」。',quiz:{blank:'ずにすんだ',distractors:['ずにはいられなかった','ずじまいだった','ざるを得なかった']}},{id:'n2-g190',pattern:'〜で済む',connection:'名詞 ＋ で済む',meaning:'〜就能了事',example:{ja:'軽いけがで済んだのは幸いだった。',zh:'只受了輕傷，真是幸運。',highlight:'軽いけがで済んだ'},tip:'表示以較輕的程度就解決了，常見「〜だけで済む」「〜で済んでよかった」。',quiz:{blank:'で済んだ',distractors:['に限った','に反した','に応じた']}},{id:'n2-g191',pattern:'〜ずじまい',connection:'動詞ない形去ない ＋ ずじまい（する→せずじまい）',meaning:'最終沒能〜',example:{ja:'結局、犯人の本名は聞かずじまいだった。',zh:'結果最終沒問到犯人的本名。',highlight:'聞かずじまい'},tip:'表示想做卻最終沒做成，帶遺憾語氣，常作「〜ずじまいだった」。「する」變「せずじまい」。',quiz:{blank:'ずじまい',distractors:['ずにすむ','ざるを得ない','ずにはおかない']}},{id:'n2-g192',pattern:'〜傾向がある',connection:'名詞の／動詞辭書形・ない形 ＋ 傾向がある',meaning:'有〜的傾向',example:{ja:'最近の若者は新聞を読まない傾向がある。',zh:'最近的年輕人有不看報紙的傾向。',highlight:'読まない傾向がある'},tip:'客觀描述整體趨勢，書面語。「〜きらいがある」則帶負面評價，常一起比較。',quiz:{blank:'傾向がある',distractors:['わけがある','ほかない','までもない']}},{id:'n2-g193',pattern:'〜ないとも限らない',connection:'動詞ない形 ＋ とも限らない（〜ないとも限らない）',meaning:'也不一定不會〜（有可能）',example:{ja:'犯人がまた現れないとも限らない。',zh:'犯人也不是不可能再出現。',highlight:'現れないとも限らない'},tip:'表示雖可能性低但不能排除，後項常有「〜から、〜ておこう」等防範。',quiz:{blank:'とも限らない',distractors:['わけがない','までもない','ほかない']}},{id:'n2-g194',pattern:'〜てもさしつかえない',connection:'動詞て形 ＋ もさしつかえない',meaning:'〜也無妨',example:{ja:'ここに車を止めてもさしつかえない。',zh:'車停在這裡也無妨。',highlight:'止めてもさしつかえない'},tip:'比「〜てもいい」正式客氣，用於表示許可。「さしつかえ」寫作「差し支え」。',quiz:{blank:'てもさしつかえない',distractors:['てはいけない','てはいられない','ても始まらない']}},{id:'n2-g195',pattern:'〜くらいなら',connection:'動詞辭書形 ＋ くらいなら',meaning:'與其〜不如',example:{ja:'うそをつくくらいなら、黙っていたほうがいい。',zh:'與其說謊，不如保持沉默。',highlight:'つくくらいなら'},tip:'前項為極不願做的事，後項常接「〜ほうがましだ」「〜ほうがいい」。',quiz:{blank:'くらいなら',distractors:['ばかりか','とたん','うえに']}},{id:'n2-g196',pattern:'〜として〜ない',connection:'一 ＋ 助數詞 ＋ として ＋ 否定',meaning:'沒有一個〜',example:{ja:'一人として、真相を知る者はいなかった。',zh:'沒有任何一個人知道真相。',highlight:'一人として'},tip:'「一＋助數詞＋として〜ない」表示全部否定，如「一日として」「一人として」，後項必為否定。',quiz:{blank:'として',distractors:['にとって','にしては','ばかり']}},{id:'n2-g197',pattern:'〜としては',connection:'名詞 ＋ としては',meaning:'作為〜來說',example:{ja:'警察としては、これ以上何もできない。',zh:'就警方而言，無法再做什麼了。',highlight:'警察としては'},tip:'表示站在某立場或身分來說。「にしては」表示與預期不符，常被當作干擾選項。',quiz:{blank:'としては',distractors:['にかけては','にしては','ときたら']}},{id:'n2-g198',pattern:'〜かいがある',connection:'動詞た形／名詞の ＋ かいがある',meaning:'〜有價值；沒白〜',example:{ja:'徹夜したかいがあって、事件が解決した。',zh:'熬夜沒白費，案件解決了。',highlight:'徹夜したかいがあって'},tip:'表示努力得到回報；否定「〜かいもなく」表示白費。漢字為「甲斐」。',quiz:{blank:'かいがあって',distractors:['ばかりに','わりに','せいで']}},{id:'n2-g199',pattern:'〜がい',connection:'動詞ます形 ＋ がい',meaning:'〜的價值',example:{ja:'この仕事にはやりがいがある。',zh:'這份工作很有成就感。',highlight:'やりがい'},tip:'接ます形構成名詞，如「やりがい」「生きがい」「働きがい」，表示做該事的價值。',quiz:{blank:'がい',distractors:['かけ','きり','っぱなし']}},{id:'n2-g200',pattern:'〜がてら',connection:'名詞／動詞ます形 ＋ がてら',meaning:'順便〜',example:{ja:'散歩がてら、現場の周りを歩いてみた。',zh:'趁著散步，順便到現場周圍走了走。',highlight:'散歩がてら'},tip:'前項多為散步、買物等移動行為，順便做後項。與「ついでに」相近，但較書面。',quiz:{blank:'がてら',distractors:['あまり','ながらも','ばかりか']}},{id:'n2-g201',pattern:'〜のもとで',connection:'名詞 ＋ のもとで',meaning:'在〜之下',example:{ja:'名探偵の指導のもとで、推理を学んだ。',zh:'在名偵探指導下學習推理。',highlight:'指導のもとで'},tip:'表示在某人指導、影響或條件下，也作「のもとに」。常見「〜の指導のもとで」。',quiz:{blank:'のもとで',distractors:['のあまり','の末に','のわりに']}},{id:'n2-g202',pattern:'〜てはいられない',connection:'動詞て形 ＋ はいられない',meaning:'不能一直〜',example:{ja:'いつまでも泣いてはいられない。',zh:'不能一直哭下去。',highlight:'泣いてはいられない'},tip:'表示情況緊迫不能再繼續某狀態，常與「いつまでも」「のんびり」搭配。',quiz:{blank:'てはいられない',distractors:['てもかまわない','てばかりいる','てならない']}},{id:'n2-g203',pattern:'〜て何よりだ',connection:'動詞て形／名詞で ＋ 何よりだ',meaning:'〜真是太好了',example:{ja:'無事で何よりだ。',zh:'平安無事真是太好了。',highlight:'無事で何よりだ'},tip:'表示這比什麼都好，多用於對他人情況表示欣慰，常見「お元気で何よりです」。',quiz:{blank:'何よりだ',distractors:['たまらない','ならない','しかたがない']}},{id:'n2-g204',pattern:'〜としか言いようがない',connection:'普通形 ＋ としか言いようがない',meaning:'只能說是〜',example:{ja:'これは偶然としか言いようがない。',zh:'這只能說是巧合。',highlight:'偶然としか言いようがない'},tip:'表示除此之外找不到其他說法，帶強烈主觀評價。名詞直接接續。',quiz:{blank:'としか言いようがない',distractors:['とは限らない','どころではない','ばかりだ']}},{id:'n2-g205',pattern:'〜ても始まらない',connection:'動詞て形 ＋ も始まらない',meaning:'〜也無濟於事',example:{ja:'今さら後悔しても始まらない。',zh:'事到如今後悔也無濟於事。',highlight:'後悔しても始まらない'},tip:'表示做了也沒用、無濟於事，口語。與「〜てもしかたがない」同義。',quiz:{blank:'ても始まらない',distractors:['てならない','てこそだ','てもかまわない']}},{id:'n2-g206',pattern:'〜も同然だ',connection:'名詞／動詞た形 ＋ も同然だ',meaning:'和〜一樣；等於〜',example:{ja:'証拠が見つかった以上、事件は解決したも同然だ。',zh:'既然找到了證據，案件等於解決了。',highlight:'解決したも同然だ'},tip:'表示雖非完全如此但實質上等同。名詞直接接「も同然だ」，如「新品も同然」。',quiz:{blank:'も同然だ',distractors:['どころではない','わけがない','ものか']}},{id:'n2-g207',pattern:'〜でしかない',connection:'名詞 ＋ でしかない',meaning:'只不過是〜',example:{ja:'それは言い訳でしかない。',zh:'那只不過是藉口。',highlight:'言い訳でしかない'},tip:'表示只不過是〜，帶輕視語氣。與「〜にすぎない」同義。',quiz:{blank:'でしかない',distractors:['どころではない','とは限らない','ではいられない']}},{id:'n2-g208',pattern:'〜ほうがましだ',connection:'動詞辭書形 ＋ ほうがましだ',meaning:'還不如〜',example:{ja:'あんな男に頼るくらいなら、一人でやるほうがましだ。',zh:'與其靠那種人，還不如一個人做。',highlight:'一人でやるほうがましだ'},tip:'表示兩者都不好但選較不壞的一方，常與「〜くらいなら」呼應出題。',quiz:{blank:'ほうがましだ',distractors:['どころではない','までもない','わけがない']}},{id:'n2-g209',pattern:'〜ときたら',connection:'名詞 ＋ ときたら',meaning:'說到〜（抱怨）',example:{ja:'うちの助手ときたら、また寝坊だ。',zh:'說到我們家助手，又睡過頭了。',highlight:'助手ときたら'},tip:'提出話題並帶抱怨、不滿，口語。後項多為負面評價，不能用於讚美。',quiz:{blank:'ときたら',distractors:['といえども','にしては','だけあって']}},{id:'n2-g210',pattern:'〜かというと',connection:'疑問詞 ＋ 普通形 ＋ かというと',meaning:'要說〜的話',example:{ja:'なぜ彼が怪しいかというと、うそをついているからだ。',zh:'要說為什麼他可疑，是因為他在說謊。',highlight:'怪しいかというと'},tip:'先提出疑問再說明原因，後面常以「〜からだ」「〜のだ」呼應。',quiz:{blank:'かというと',distractors:['かどうか','かのように','からには']}},{id:'n2-g211',pattern:'〜とともに（變化）',connection:'動詞辭書形／名詞 ＋ とともに',meaning:'隨著〜',example:{ja:'年を取るとともに、記憶力が衰える。',zh:'隨著年紀增長，記憶力衰退。',highlight:'取るとともに'},tip:'表示隨著前項變化後項也變化，同「につれて」「にしたがって」。',quiz:{blank:'とともに',distractors:['うえで','あまり','かぎり']}},{id:'n2-g212',pattern:'〜とともに（一起）',connection:'名詞 ＋ とともに',meaning:'和〜一起',example:{ja:'仲間とともに、難事件を解決した。',zh:'和夥伴一起解決了難解的案件。',highlight:'仲間とともに'},tip:'「名詞＋とともに」表示和〜一起，比「と一緒に」書面。也可表示「同時」。',quiz:{blank:'とともに',distractors:['にとって','において','に対して']}},{id:'n2-g213',pattern:'〜際に',connection:'名詞の／動詞辭書形・た形 ＋ 際に',meaning:'〜的時候（正式）',example:{ja:'お帰りの際に、忘れ物にご注意ください。',zh:'回去時請注意別忘了東西。',highlight:'お帰りの際に'},tip:'「〜の際に」是「〜とき」的正式說法，常見於公告、商務文書。',quiz:{blank:'際に',distractors:['末に','あまり','最中に']}},{id:'n2-g214',pattern:'〜折に',connection:'名詞の／動詞辭書形・た形 ＋ 折に（は）',meaning:'〜的時候（書面、客氣）',example:{ja:'お近くにお越しの折には、ぜひお立ち寄りください。',zh:'來到附近時請務必順道光臨。',highlight:'お越しの折には'},tip:'比「際」更客氣、文雅，多用於好的機會，常見於書信「〜の折には」。不用於負面場合。',quiz:{blank:'折には',distractors:['末には','わりには','ばかりには']}},{id:'n2-g215',pattern:'〜ままに',connection:'動詞辭書形・受身形 ＋ ままに',meaning:'順著〜；任憑〜',example:{ja:'言われるままに、彼は書類にサインした。',zh:'他照著別人說的在文件上簽了名。',highlight:'言われるままに'},tip:'表示順從他人或自然而為，常見「言われるままに」「思うままに」「気の向くままに」。',quiz:{blank:'ままに',distractors:['ばかりに','あまりに','かぎりに']}},{id:'n2-g216',pattern:'〜つ〜つ',connection:'動詞ます形 ＋ つ ＋ 動詞ます形 ＋ つ',meaning:'時而〜時而〜；互相〜',example:{ja:'二人は抜きつ抜かれつの勝負を続けた。',zh:'兩人持續著你追我趕的比賽。',highlight:'抜きつ抜かれつ'},tip:'前後常為主動與被動或相反動詞，屬慣用語，如「持ちつ持たれつ」「行きつ戻りつ」。',quiz:{blank:'抜かれつ',distractors:['抜かれて','抜かれず','抜かれた']}},{id:'n2-g217',pattern:'〜やら〜やら',connection:'名詞／普通形 ＋ やら',meaning:'又是〜又是〜',example:{ja:'引っ越しやら仕事やらで、毎日忙しい。',zh:'又是搬家又是工作，每天都很忙。',highlight:'引っ越しやら仕事やら'},tip:'列舉多項事物，帶「又是〜又是〜，真受不了」的語氣，後項多為忙碌、困擾。',quiz:{blank:'やらで',distractors:['なりで','ばかりで','までで']}},{id:'n2-g218',pattern:'〜だの〜だの',connection:'名詞／普通形 ＋ だの',meaning:'〜啦〜啦（抱怨列舉）',example:{ja:'高いだの遠いだの、文句ばかり言う。',zh:'又嫌貴又嫌遠，盡是抱怨。',highlight:'高いだの遠いだの'},tip:'列舉時帶不滿、抱怨語氣，口語。與「やら」相比更有責備感，常接「文句を言う」。',quiz:{blank:'だの、',distractors:['なら、','のに、','ので、']}},{id:'n2-g219',pattern:'〜というか〜というか',connection:'名詞／普通形 ＋ というか',meaning:'該說是〜還是〜',example:{ja:'彼は大胆というか無謀というか、一人で乗り込んだ。',zh:'他該說大膽還是魯莽，竟一個人闖了進去。',highlight:'大胆というか無謀というか'},tip:'表示難以找到準確說法而並列兩種評價，口語。後項常為說話者的感想。',quiz:{blank:'というか、',distractors:['といっても、','とはいえ、','というのに、']}},{id:'n2-g220',pattern:'〜もしない',connection:'動詞ます形 ＋ もしない',meaning:'連〜都不',example:{ja:'彼は振り向きもしないで、去っていった。',zh:'他連頭也不回就走了。',highlight:'振り向きもしない'},tip:'強調連最基本的動作都不做，帶不滿語氣，常見「見向きもしない」「振り向きもしない」。',quiz:{blank:'もしない',distractors:['つつ','がてら','ながら']}},{id:'n2-g221',pattern:'〜わけだから',connection:'普通形 ＋ わけだから',meaning:'既然〜（理所當然）',example:{ja:'鍵を持っていたのは彼だけだったわけだから、疑われて当然だ。',zh:'既然只有他持有鑰匙，被懷疑也是理所當然。',highlight:'彼だけだったわけだから'},tip:'表示根據事實理所當然得出結論，後項常為「〜当然だ」「〜はずだ」。',quiz:{blank:'わけだから',distractors:['ものの','くせに','にしては']}}]},1908,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"N2_READING",{enumerable:!0,get:function(){return n}});const n=[{id:"n2-r01",title:"片付けられない理由",titleZh:"無法整理的原因",topic:"生活",paragraphs:[{ja:"部屋を片付けようと決心しても、気がつくと元の散らかった状態に戻っている。そんな経験を持つ人は少なくないだろう。私自身もその一人で、毎年年末になると大掃除をするのだが、春になるころには机の上に書類や本が山のように積まれている。なぜ片付けた状態を保つことができないのだろうか。",zh:"即使下定決心要整理房間，回過神來卻發現又回到原本凌亂的狀態。有這種經驗的人應該不少吧。我自己也是其中之一，每年到了年底都會大掃除，但到了春天，桌上又堆滿了像小山一樣的文件和書。為什麼無法維持整理好的狀態呢？"},{ja:"ある整理の専門家によると、片付けが苦手な人の多くは「いつか使うかもしれない」という考えから物を捨てられないのだという。確かに、私の引き出しには何年も使っていない文房具や、もらったまま開けていない贈り物がたくさん入っている。もったいないと思う気持ちは悪くないが、使わない物を持ち続けることは、かえって物を大切にしていないことになるのではないか。",zh:"據某位整理專家說，許多不擅長整理的人，是因為「說不定哪天會用到」的想法而丟不掉東西。的確，我的抽屜裡放了很多好幾年沒用過的文具，以及收到後一直沒拆開的禮物。覺得可惜的心情並不壞，但一直留著不用的東西，反而不就等於沒有珍惜物品嗎？"},{ja:"また、物の置き場所が決まっていないことも、散らかる原因の一つだそうだ。使った物をどこに戻せばいいのかわからなければ、とりあえず近くに置いてしまう。それが繰り返されるうちに、部屋はあっという間に散らかってしまうわけだ。逆に言えば、すべての物に「住所」を決めておけば、片付けは習慣として続けやすくなる。",zh:"另外，物品沒有固定的擺放位置，據說也是變亂的原因之一。如果不知道用過的東西該放回哪裡，就會先隨手放在附近。這樣反覆下來，房間轉眼間就變亂了。反過來說，只要替所有東西決定好「住址」，整理就比較容易養成習慣並持續下去。"},{ja:"この話を聞いて、私は一度にすべてを片付けようとするのをやめることにした。一日に一つの引き出しだけを整理し、一年以上使っていない物は思い切って手放す。そして残した物には必ず置き場所を決める。始めてまだ一か月ほどだが、以前よりも探し物をする時間が減り、気持ちにも余裕が生まれたように感じている。",zh:"聽了這番話，我決定不再試圖一次整理完所有東西。一天只整理一個抽屜，一年以上沒用的東西就果斷放手。然後替留下來的東西一定決定好擺放位置。雖然才開始一個月左右，但我覺得找東西的時間比以前少了，心情上也多了一些餘裕。"},{ja:"片付けとは、単に部屋をきれいにすることではなく、自分にとって本当に必要な物は何かを考えることなのかもしれない。物を減らすことで、生活そのものが少し軽くなったような気がする。",zh:"所謂整理，或許不只是把房間弄乾淨，而是思考對自己來說真正需要的東西是什麼。藉由減少物品，我覺得生活本身似乎也變得輕鬆了一點。"}],vocab:[{word:"決心",reading:"けっしん",meaning:"決心、下定決心"},{word:"散らかる",reading:"ちらかる",meaning:"凌亂、散亂"},{word:"専門家",reading:"せんもんか",meaning:"專家"},{word:"引き出し",reading:"ひきだし",meaning:"抽屜"},{word:"習慣",reading:"しゅうかん",meaning:"習慣"},{word:"思い切って",reading:"おもいきって",meaning:"果斷地、下定決心地"},{word:"手放す",reading:"てばなす",meaning:"放手、處理掉"},{word:"余裕",reading:"よゆう",meaning:"餘裕、從容"}],questions:[{question:"専門家によると、部屋が散らかる原因の一つは何か。",questionZh:"根據專家的說法，房間變亂的原因之一是什麼？",options:["物の置き場所が決まっていないこと","掃除をする時間が足りないこと","部屋が狭すぎること","家族が片付けに協力しないこと"]},{question:"筆者が始めた片付けの方法として正しいものはどれか。",questionZh:"下列何者是作者開始採用的整理方法？",options:["一日に一つの引き出しだけを整理する","年末に一度にすべてを片付ける","使っていない物をすべて人にあげる","新しい収納家具をたくさん買う"]},{question:"筆者は片付けをどのようなものだと考えているか。",questionZh:"作者認為整理是什麼樣的事情？",options:["自分に本当に必要な物は何かを考えること","部屋を他人にきれいに見せること","専門家に任せるべきこと","年に一度だけすればよいこと"]}]},{id:"n2-r02",title:"銭湯の魅力",titleZh:"錢湯的魅力",topic:"文化",paragraphs:[{ja:"家に風呂があるのが当たり前になった現在、町の銭湯は年々数を減らしている。しかし最近、若い世代の間で銭湯が見直されつつあるという。わざわざお金を払って、家の外の大きな風呂に入りに行く。その魅力はいったいどこにあるのだろうか。",zh:"在家裡有浴室已成為理所當然的現在，街上的錢湯（公共澡堂）數量逐年減少。但據說最近在年輕世代之間，錢湯正重新受到重視。特地花錢去外面的大浴池泡澡，它的魅力究竟在哪裡呢？"},{ja:"まず挙げられるのは、広い湯船でゆっくり手足を伸ばせる気持ちよさだ。家の狭い風呂ではなかなか味わえない開放感がある。また、多くの銭湯の壁には富士山などの大きな絵が描かれていて、それを眺めながら湯につかっていると、まるで旅行に来たような気分になれる。",zh:"首先可以舉出的，是能在寬敞的浴池裡悠閒伸展手腳的舒暢感。那是在家裡狹小的浴室很難體會到的開闊感。此外，許多錢湯的牆上畫著富士山等大幅畫作，一邊眺望一邊泡在熱水裡，就彷彿來旅行一樣。"},{ja:"次に、人とのつながりが感じられる点も見逃せない。昔の銭湯は、近所の人々が顔を合わせ、世間話をする場所でもあった。今でも常連の客同士が挨拶を交わしたり、初めて来た客に入り方を教えてあげたりする光景が見られる。知らない人と同じ湯に入るという体験は、一人暮らしが増えた現代において、かえって新鮮に感じられるのかもしれない。",zh:"其次，能感受到人與人之間的連結這一點也不容忽視。以前的錢湯也是鄰居們見面、閒話家常的地方。現在仍能看到常客彼此打招呼，或教第一次來的客人如何泡澡的景象。和陌生人泡同一池熱水的體驗，在獨居者增加的現代，或許反而讓人覺得新鮮。"},{ja:"一方で、銭湯にはいくつかのマナーがある。湯船に入る前に体を洗うこと、タオルを湯の中に入れないこと、大声で話さないことなどだ。こうした決まりは面倒に思えるかもしれないが、多くの人が気持ちよく過ごすための工夫だと考えれば、納得できるだろう。",zh:"另一方面，錢湯有一些禮儀。像是進浴池前要先洗身體、不把毛巾放進熱水裡、不大聲說話等。這些規矩也許看起來很麻煩，但若想成是為了讓大家都能舒服度過的用心，應該就能理解了吧。"},{ja:"銭湯は単なる入浴の場ではなく、地域の文化を伝える場所でもある。経営を続けるのが難しい銭湯も多いと聞くが、この魅力が次の世代にも受け継がれていくことを願いたい。",zh:"錢湯不只是洗澡的地方，也是傳承地方文化的場所。聽說很多錢湯難以繼續經營，但我希望這份魅力能傳承給下一個世代。"}],vocab:[{word:"見直す",reading:"みなおす",meaning:"重新評價、重新審視"},{word:"湯船",reading:"ゆぶね",meaning:"浴池、浴缸"},{word:"開放感",reading:"かいほうかん",meaning:"開闊感、解放感"},{word:"眺める",reading:"ながめる",meaning:"眺望、凝視"},{word:"常連",reading:"じょうれん",meaning:"常客"},{word:"世間話",reading:"せけんばなし",meaning:"閒聊、閒話家常"},{word:"納得",reading:"なっとく",meaning:"理解、認同"},{word:"受け継ぐ",reading:"うけつぐ",meaning:"繼承、傳承"}],questions:[{question:"筆者によると、銭湯の壁の絵にはどんな効果があるか。",questionZh:"根據作者的說法，錢湯牆上的畫有什麼效果？",options:["旅行に来たような気分になれる","体が早く温まる","客同士の会話が増える","入浴のマナーが自然に学べる"]},{question:"昔の銭湯は、入浴のほかにどのような場所でもあったか。",questionZh:"以前的錢湯除了洗澡之外，還是什麼樣的地方？",options:["近所の人々が世間話をする場所","子どもたちが勉強をする場所","旅行者が泊まる場所","画家が絵を売る場所"]},{question:"銭湯のマナーとして、本文に書かれていないものはどれか。",questionZh:"下列何者是文中「沒有」提到的錢湯禮儀？",options:["湯船の中で泳がないこと","湯船に入る前に体を洗うこと","タオルを湯の中に入れないこと","大声で話さないこと"]}]},{id:"n2-r03",title:"無人販売所と信頼",titleZh:"無人販售所與信任",topic:"社會",paragraphs:[{ja:"田舎の道を車で走っていると、道端に小さな小屋が建っていて、野菜が並べられているのを見かけることがある。そこには店員はおらず、代金を入れる箱が置いてあるだけだ。いわゆる「無人販売所」である。客は自分で商品を選び、決められた金額を箱に入れて持ち帰る。",zh:"開車行駛在鄉間道路時，有時會看到路邊蓋著小棚子，上面擺著蔬菜。那裡沒有店員，只放了一個投錢的箱子。這就是所謂的「無人販售所」。客人自己挑選商品，把規定的金額放進箱子後帶回家。"},{ja:"外国から来た友人をこうした販売所に案内したところ、彼はとても驚いていた。誰も見ていないのに、なぜ人々はきちんとお金を払うのか、というのだ。彼の国では、このような売り方はとても考えられないらしい。言われてみれば、確かに不思議な仕組みである。",zh:"我帶來自國外的朋友去這種販售所時，他非常驚訝。他說，明明沒有人在看，為什麼大家還會乖乖付錢呢？在他的國家，這種賣法似乎是完全無法想像的。被他這麼一說，這確實是個不可思議的機制。"},{ja:"もちろん、すべての客が正直だとは限らない。実際、お金を払わずに商品を持っていく人がいて困っているという話もよく耳にする。最近では、防犯カメラを設置したり、電子決済を導入したりする販売所も増えてきた。それでも多くの農家がこの方法を続けているのは、人件費がかからないうえに、売れ残りそうな野菜を少しでも無駄にせずに済むからだ。",zh:"當然，並非所有客人都是誠實的。實際上也常聽到有人不付錢就拿走商品、讓人困擾的事。最近，裝設監視器或導入電子支付的販售所也增加了。即使如此，許多農家仍繼續採用這種方法，是因為不需要人事費用，而且能讓可能賣不完的蔬菜盡量不浪費。"},{ja:"しかし、この仕組みを支えているのは、経済的な理由だけではないだろう。売る側は「客は正直に払ってくれるはずだ」と信じ、買う側はその信頼を裏切りたくないと考える。お互いの顔は見えなくても、そこには目に見えない約束のようなものが存在している。",zh:"然而，支撐這個機制的應該不只是經濟上的理由。賣方相信「客人應該會誠實付錢」，買方則不想辜負這份信任。即使看不見彼此的臉，那裡仍存在著一種像是看不見的約定般的東西。"},{ja:"社会がどれほど便利になっても、人を信じる気持ちがなければ成り立たないものがある。小さな無人販売所は、そのことを静かに教えてくれているように思う。",zh:"無論社會變得多麼便利，有些事情若沒有信任他人的心就無法成立。我覺得小小的無人販售所，正靜靜地告訴我們這件事。"}],vocab:[{word:"道端",reading:"みちばた",meaning:"路邊"},{word:"代金",reading:"だいきん",meaning:"貨款、費用"},{word:"仕組み",reading:"しくみ",meaning:"機制、結構"},{word:"設置",reading:"せっち",meaning:"設置、裝設"},{word:"導入",reading:"どうにゅう",meaning:"導入、引進"},{word:"人件費",reading:"じんけんひ",meaning:"人事費用"},{word:"裏切る",reading:"うらぎる",meaning:"背叛、辜負"},{word:"成り立つ",reading:"なりたつ",meaning:"成立"}],questions:[{question:"外国から来た友人が驚いたのはなぜか。",questionZh:"來自國外的朋友為什麼感到驚訝？",options:["誰も見ていないのに人々がお金を払うから","野菜の値段がとても安かったから","道端に販売所がたくさんあったから","店員が外国語を話せたから"]},{question:"農家が無人販売を続ける理由として、本文に書かれているものはどれか。",questionZh:"下列何者是文中提到的農家持續無人販售的理由？",options:["人件費がかからないから","防犯カメラが安く買えるから","客と話をしたくないから","税金を払わなくてよいから"]},{question:"筆者が最も言いたいことは何か。",questionZh:"作者最想表達的是什麼？",options:["社会には人を信じる気持ちによって成り立つものがある","無人販売所にはもっと防犯対策が必要だ","外国にも無人販売所を広めるべきだ","電子決済をすべての店に導入するべきだ"]}]},{id:"n2-r04",title:"都会のカラス",titleZh:"都市裡的烏鴉",topic:"自然",paragraphs:[{ja:"朝、ごみ置き場の近くを通ると、カラスが袋を破って中身を散らかしていることがある。そのため、カラスは迷惑な鳥として嫌われることが多い。しかし、カラスの行動を詳しく観察してみると、その頭の良さに驚かされる。",zh:"早上經過垃圾集中處附近時，有時會看到烏鴉把袋子啄破、把裡面的東西弄得到處都是。因此，烏鴉常被當成討人厭的鳥。但是仔細觀察烏鴉的行為，就會對牠們的聰明感到驚訝。"},{ja:"たとえば、カラスは人の顔を見分けることができると言われている。自分に危害を加えた人のことは長い間覚えていて、その人が近づくと大きな声で鳴いて仲間に知らせるそうだ。また、硬いクルミの殻を割るために、わざと道路に置いて車にひかせるカラスがいるという報告もある。これほど複雑な行動ができる鳥は、ほかにあまり例がない。",zh:"例如，據說烏鴉能辨認人的臉。牠們會長時間記得曾經傷害自己的人，當那個人靠近時，就會大聲鳴叫通知同伴。另外也有報告指出，有些烏鴉為了敲開堅硬的核桃殼，會故意把核桃放在馬路上讓車子輾過。能做出這麼複雜行為的鳥，其他幾乎沒有例子。"},{ja:"カラスが都会で数を増やしたのは、人間の暮らしと深く関係している。都会には食べ物が豊富にあり、高いビルや公園の木は巣を作るのに都合がよい。つまり、カラスは人間が作り出した環境にうまく適応した結果、私たちの身近に住むようになったのである。",zh:"烏鴉在都市中數量增加，與人類的生活密切相關。都市裡食物豐富，高樓和公園的樹木也很適合築巢。也就是說，烏鴉是成功適應了人類所創造的環境，結果才開始住在我們身邊。"},{ja:"最近では、ごみ置き場にネットをかけたり、ごみを出す時間を守るよう呼びかけたりする地域が増えている。こうした取り組みによって食べ物が手に入りにくくなると、カラスの数は自然と減っていくという。カラスを追い払うより、カラスが集まる原因を減らすことのほうが効果的なのだ。",zh:"最近，在垃圾集中處蓋上網子、呼籲居民遵守倒垃圾時間的地區越來越多。據說透過這些措施讓烏鴉難以取得食物後，烏鴉的數量自然就會減少。與其驅趕烏鴉，減少烏鴉聚集的原因反而更有效。"},{ja:"嫌われ者のカラスだが、彼らが増えた背景には私たち人間の生活がある。カラスの問題を考えることは、自分たちの暮らし方を見直すことにもつながるのではないだろうか。",zh:"烏鴉雖然惹人厭，但牠們增加的背後，有著我們人類的生活。思考烏鴉的問題，或許也能促使我們重新審視自己的生活方式吧。"}],vocab:[{word:"観察",reading:"かんさつ",meaning:"觀察"},{word:"見分ける",reading:"みわける",meaning:"辨別、分辨"},{word:"危害",reading:"きがい",meaning:"危害、傷害"},{word:"殻",reading:"から",meaning:"殼"},{word:"豊富",reading:"ほうふ",meaning:"豐富"},{word:"適応",reading:"てきおう",meaning:"適應"},{word:"追い払う",reading:"おいはらう",meaning:"趕走、驅逐"},{word:"背景",reading:"はいけい",meaning:"背景"}],questions:[{question:"カラスの頭の良さを示す例として、本文にあるものはどれか。",questionZh:"下列何者是文中用來說明烏鴉聰明的例子？",options:["人の顔を見分けることができる","人の言葉をまねすることができる","十まで数を数えることができる","ごみを出す曜日を覚えている"]},{question:"カラスが都会で増えたのはなぜか。",questionZh:"烏鴉為什麼在都市中增加？",options:["人間が作った環境にうまく適応したから","山に食べ物がまったくなくなったから","人間がカラスを保護しているから","都会からほかの鳥がいなくなったから"]},{question:"筆者によると、カラスを減らすために効果的なのはどんなことか。",questionZh:"根據作者的說法，什麼做法對減少烏鴉有效？",options:["カラスが集まる原因を減らすこと","大きな音を出してカラスを追い払うこと","カラスの巣をすべて壊すこと","カラスに別の食べ物を与えること"]}]},{id:"n2-r05",title:"眠りと記憶",titleZh:"睡眠與記憶",topic:"科學",paragraphs:[{ja:"試験の前の晩、眠る時間を削って勉強した経験がある人は多いだろう。少しでも長く勉強したほうが、たくさん覚えられるような気がするからだ。ところが、最近の研究によると、こうした方法は必ずしも効果的ではないらしい。",zh:"應該有很多人有過在考試前一晚犧牲睡眠時間念書的經驗吧。因為總覺得多念一點，就能記住更多東西。然而，根據最近的研究，這種方法似乎未必有效。"},{ja:"私たちが眠っている間、脳は休んでいるわけではない。昼間に経験したことや学んだことを整理し、必要な情報を長く覚えておけるように保存しているのである。ある実験では、単語を覚えた後に十分に眠ったグループのほうが、眠らずに過ごしたグループよりも、翌日のテストで良い成績を取ったという結果が出ている。",zh:"我們睡覺的時候，大腦並不是在休息。它會整理白天經歷和學到的事情，並把需要的資訊保存下來，以便長久記住。在某項實驗中，背完單字後睡飽的那一組，比沒有睡覺的那一組在隔天的測驗中取得了更好的成績。"},{ja:"また、睡眠には、新しい考えを生み出す働きもあるとされている。解けなかった問題の答えが、一晩寝た後にふと思いつくことがあるのは、眠っている間に脳が情報を結びつけ直しているためだと考えられている。「難しいことは一晩寝てから決めよ」という言葉があるが、これにはどうやら科学的な根拠があるようだ。",zh:"此外，一般認為睡眠也有產生新想法的作用。解不出來的問題，有時睡一晚後會突然想到答案，這被認為是因為大腦在睡眠期間重新連結了資訊。有句話說「困難的事睡一晚再決定」，看來這句話似乎有科學根據。"},{ja:"もっとも、ただ長く眠ればよいというものではない。寝る直前までスマートフォンの画面を見ていると、脳が興奮して眠りが浅くなってしまう。毎日同じ時刻に寝起きし、寝る前は明るい光を避けるなど、睡眠の質を高める工夫が大切である。",zh:"不過，並不是睡得久就好。如果睡前一直盯著手機螢幕，大腦會變得興奮，睡眠就會變淺。每天在同一時間就寢和起床、睡前避開明亮的光線等，提高睡眠品質的方法很重要。"},{ja:"睡眠時間を減らして努力することは、一見まじめな態度に見える。しかし、本当に成果を上げたいのであれば、しっかり眠ることも学習の一部だと考えるべきだろう。",zh:"減少睡眠時間來努力，乍看之下是很認真的態度。但是，如果真的想要有成果，就應該把好好睡覺也當成學習的一部分。"}],vocab:[{word:"削る",reading:"けずる",meaning:"削減、刪減"},{word:"保存",reading:"ほぞん",meaning:"保存"},{word:"実験",reading:"じっけん",meaning:"實驗"},{word:"睡眠",reading:"すいみん",meaning:"睡眠"},{word:"根拠",reading:"こんきょ",meaning:"根據"},{word:"興奮",reading:"こうふん",meaning:"興奮"},{word:"避ける",reading:"さける",meaning:"避開"},{word:"成果",reading:"せいか",meaning:"成果"}],questions:[{question:"私たちが眠っている間、脳は何をしているか。",questionZh:"我們睡覺的時候，大腦在做什麼？",options:["学んだことを整理し、保存している","完全に休んで何もしていない","次の日の予定を立てている","古い記憶をすべて消している"]},{question:"本文で紹介されている実験の結果として正しいものはどれか。",questionZh:"關於文中介紹的實驗結果，下列何者正確？",options:["十分に眠ったグループのほうがテストの成績が良かった","眠らなかったグループのほうがテストの成績が良かった","二つのグループの成績はほとんど同じだった","長く眠りすぎたグループは成績が悪かった"]},{question:"睡眠の質を高める工夫として、本文の内容に合うものはどれか。",questionZh:"下列何者符合文中提到的提高睡眠品質的方法？",options:["寝る前は明るい光を避ける","寝る直前までスマートフォンを見る","休みの日にまとめて長く寝る","寝る前に熱いお茶を飲む"]}]},{id:"n2-r06",title:"雪の朝の足跡",titleZh:"雪晨的足跡",topic:"推理",paragraphs:[{ja:"ある冬の朝、探偵の森川は古い友人の山本から電話を受けた。山本が経営する小さな旅館で、客から預かっていた高価な腕時計がなくなったというのだ。森川が急いで旅館に向かうと、辺りは前の晩から降り続いた雪で真っ白になっていた。",zh:"某個冬天的早晨，偵探森川接到老朋友山本的電話。山本說，他經營的小旅館裡，替客人保管的一只昂貴手錶不見了。森川急忙趕往旅館，四周因為從前一晚下個不停的雪而一片雪白。"},{ja:"山本の話によると、腕時計は夜十時に帳場の引き出しにしまわれた。従業員の佐藤は十一時まで帳場にいたが、その間は誰も近づかなかったという。佐藤が自分の部屋に戻った後、朝六時に山本が確認すると、腕時計は消えていた。なお、雪は夜十一時ごろにやんだそうだ。",zh:"據山本說，手錶在晚上十點被收進櫃檯的抽屜。員工佐藤一直待在櫃檯到十一點，據說這段期間沒有任何人靠近。佐藤回到自己房間後，早上六點山本確認時，手錶已經不見了。另外，雪據說在晚上十一點左右停了。"},{ja:"その夜旅館にいたのは、佐藤のほかに、宿泊客の田中と料理人の木村だった。田中は「十時には寝ていて、朝まで一度も部屋を出なかった」と話した。木村は「仕事を終えて、十時半ごろ歩いて家に帰った。雪が強くて大変だった」と答えた。森川が外に出てみると、旅館の裏口から木村の家の方向へ、一筋の足跡がはっきりと残っていた。",zh:"那天晚上在旅館的，除了佐藤之外，還有住宿客人田中和廚師木村。田中說：「我十點就睡了，到早上都沒離開過房間。」木村回答：「我做完工作，十點半左右走路回家。雪很大，很辛苦。」森川走到外面一看，從旅館後門往木村家的方向，清楚留著一行足跡。"},{ja:"森川はしばらく足跡を見つめた後、静かに言った。「木村さん、あなたが帰ったのは十時半ではありませんね。雪は十一時までやまなかった。もし十時半に出たのなら、足跡はその後に降った雪で消えているか、少なくともぼやけているはずです。これほどくっきり残っているのは、雪がやんだ後に歩いた証拠です。」",zh:"森川凝視足跡一會兒後，平靜地說：「木村先生，您回去的時間並不是十點半吧。雪一直到十一點才停。如果您是十點半離開的，足跡應該會被之後下的雪蓋掉，或至少變得模糊。足跡留得這麼清楚，就是您在雪停之後才走的證據。」"},{ja:"木村の顔は真っ青になった。彼は佐藤が帳場を離れるのを待って腕時計を盗み、それから家に帰ったのだった。腕時計は木村の鞄の中から見つかり、無事に客のもとへ戻された。",zh:"木村的臉色變得慘白。原來他是等佐藤離開櫃檯後偷了手錶，然後才回家的。手錶在木村的包包裡被找到，平安地回到了客人手中。"}],vocab:[{word:"経営",reading:"けいえい",meaning:"經營"},{word:"預かる",reading:"あずかる",meaning:"保管、代為照管"},{word:"従業員",reading:"じゅうぎょういん",meaning:"員工"},{word:"宿泊客",reading:"しゅくはくきゃく",meaning:"住宿客人"},{word:"足跡",reading:"あしあと",meaning:"足跡、腳印"},{word:"証拠",reading:"しょうこ",meaning:"證據"},{word:"盗む",reading:"ぬすむ",meaning:"偷竊"},{word:"無事",reading:"ぶじ",meaning:"平安、順利"}],questions:[{question:"腕時計が盗まれたのは、いつごろだと考えられるか。",questionZh:"手錶被偷的時間，推測大約是什麼時候？",options:["夜十一時から朝六時の間","夜十時から十一時の間","夜十時より前","朝六時より後"]},{question:"宿泊客の田中は何と話したか。",questionZh:"住宿客人田中說了什麼？",options:["朝まで一度も部屋を出なかった","十時半ごろ歩いて家に帰った","十一時まで帳場にいた","夜中に雪の音で目が覚めた"]},{question:"森川が木村をうそをついていると考えた手がかりは何か。",questionZh:"森川認為木村說謊的線索是什麼？",options:["雪の上の足跡がくっきり残っていたこと","木村の鞄がとても大きかったこと","木村の靴が濡れていなかったこと","帳場の引き出しが開いたままだったこと"]}]},{id:"n2-r07",title:"手紙を書くということ",titleZh:"寫信這件事",topic:"生活",paragraphs:[{ja:"先日、引っ越しの準備をしていたら、押し入れの奥から古い箱が出てきた。中には、学生時代に友人や家族からもらった手紙がぎっしり詰まっていた。懐かしさのあまり、片付けの手を止めて一通ずつ読み返しているうちに、気がつくと外は暗くなっていた。",zh:"前幾天在準備搬家時，從壁櫥深處找出了一個舊箱子。裡面塞滿了學生時代從朋友和家人那裡收到的信。因為太懷念了，我停下整理的手一封封重讀，回過神來外面已經天黑了。"},{ja:"今では、連絡を取るのはほとんどメールやメッセージアプリである。思いついたときにすぐ送れて、相手もすぐに返事をくれる。便利であることは間違いない。しかし、何年もたってから読み返したくなるようなメッセージが、果たしてどれほどあるだろうか。",zh:"現在聯絡幾乎都靠電子郵件或通訊軟體。想到的時候馬上就能傳送，對方也會立刻回覆。方便是毫無疑問的。但是，過了好幾年後還會想重讀的訊息，究竟有多少呢？"},{ja:"手紙には、文字以外にもさまざまな情報が含まれている。丁寧に書かれた字からは相手の気持ちが伝わってくるし、書き直した跡からは、言葉を選ぶのに迷った様子がうかがえる。便箋や切手の選び方にも、その人らしさが表れる。手紙を受け取るということは、相手がかけてくれた時間と手間を受け取ることなのだと思う。",zh:"信裡除了文字之外，還包含了各式各樣的資訊。從用心寫下的字能感受到對方的心意，從改寫的痕跡則能看出對方在挑選用詞時猶豫的樣子。信紙和郵票的挑選方式也會展現出那個人的個性。我認為收到一封信，就是收下對方為你花費的時間與心力。"},{ja:"そこで私は、久しぶりに手紙を書いてみることにした。宛先は、長い間会っていない大学時代の友人だ。いざペンを持つと、何を書けばいいのか迷ってしまい、一枚書き上げるのに一時間近くかかった。それでも、相手の顔を思い浮かべながら言葉を選ぶ時間は、不思議と心が落ち着くものだった。",zh:"於是我決定久違地試著寫一封信。收件人是很久沒見面的大學時代朋友。真的拿起筆時，卻不知道該寫什麼，寫完一張花了將近一個小時。即使如此，一邊想著對方的臉一邊挑選詞句的時間，不可思議地讓人心情平靜。"},{ja:"一週間後、友人から返事が届いた。封筒を開けたときのうれしさは、メールでは決して味わえないものだった。便利さだけでは得られない価値が、手紙にはあるのだろう。",zh:"一週後，朋友寄來了回信。打開信封時的喜悅，是電子郵件絕對無法體會的。信件裡，大概有著光靠便利無法得到的價值吧。"}],vocab:[{word:"押し入れ",reading:"おしいれ",meaning:"壁櫥"},{word:"懐かしい",reading:"なつかしい",meaning:"懷念的"},{word:"含む",reading:"ふくむ",meaning:"包含"},{word:"丁寧",reading:"ていねい",meaning:"仔細、用心、有禮貌"},{word:"手間",reading:"てま",meaning:"工夫、心力"},{word:"宛先",reading:"あてさき",meaning:"收件人、收件地址"},{word:"思い浮かべる",reading:"おもいうかべる",meaning:"想起、浮現在腦海"},{word:"封筒",reading:"ふうとう",meaning:"信封"}],questions:[{question:"筆者が古い手紙を見つけたのは、どんなときか。",questionZh:"作者是在什麼時候找到舊信的？",options:["引っ越しの準備をしていたとき","年末の大掃除をしていたとき","友人の家を訪ねたとき","大学を卒業したとき"]},{question:"筆者によると、手紙の書き直した跡から何が分かるか。",questionZh:"根據作者的說法，從信上改寫的痕跡可以看出什麼？",options:["言葉を選ぶのに迷った様子","書いた人の年齢","手紙を書いた場所","相手が急いでいたこと"]},{question:"久しぶりに手紙を書いてみて、筆者はどう感じたか。",questionZh:"久違地寫信後，作者有什麼感受？",options:["言葉を選ぶ時間に不思議と心が落ち着いた","時間がかかりすぎて二度と書きたくないと思った","メールのほうが気持ちが伝わると思った","すぐに書き終えられたので驚いた"]}]},{id:"n2-r08",title:"和菓子と季節",titleZh:"和菓子與季節",topic:"文化",paragraphs:[{ja:"和菓子屋の店先をのぞくと、季節によって並んでいる菓子が変わることに気づく。春には桜の花をかたどった菓子、夏には涼しげな透明の菓子、秋には栗や柿を使った菓子が並ぶ。和菓子は、味だけでなく見た目でも季節を表現しているのである。",zh:"往和菓子店的店頭一看，就會發現陳列的點心會隨季節改變。春天有櫻花造型的點心，夏天有看起來很清涼的透明點心，秋天則擺著用栗子或柿子做的點心。和菓子不只用味道，也用外觀來表現季節。"},{ja:"こうした和菓子の多くには、美しい名前がつけられている。たとえば、同じような丸い形の菓子でも、色や模様によって「初雪」「春の野」などと呼び分けられる。名前を聞いた客は、菓子の形と言葉を重ね合わせて、その風景を想像する。いわば、食べる前から楽しみが始まっているわけだ。",zh:"這些和菓子大多取了美麗的名字。例如，即使是形狀差不多的圓形點心，也會依顏色和花紋分別稱為「初雪」、「春之原野」等。聽到名字的客人，會把點心的形狀和名字疊合在一起，想像那幅風景。可以說，樂趣在吃之前就已經開始了。"},{ja:"和菓子が季節を大切にするのは、茶道との関わりが深いからだと言われている。茶会では、季節に合わせて道具や掛け軸を選び、客をもてなす。その中で出される菓子も、季節の雰囲気を伝える大切な役割を担ってきた。職人たちは、限られた材料で四季の移り変わりを表そうと、工夫を重ねてきたのである。",zh:"據說和菓子重視季節，是因為與茶道的關係很深。茶會上會配合季節挑選器具和掛軸來款待客人。其中端出的點心，也一直擔負著傳達季節氛圍的重要角色。師傅們為了用有限的材料表現四季的變遷，不斷地下工夫。"},{ja:"ところが、生活の洋風化が進むにつれて、和菓子を日常的に食べる人は減っている。若い世代の中には、洋菓子のほうが身近だという人も多いだろう。それでも最近は、和菓子作りの体験教室が外国人観光客に人気を集めるなど、新しい形で注目されることも増えてきた。",zh:"然而，隨著生活日益西化，日常吃和菓子的人越來越少。年輕世代中，應該也有很多人覺得西式點心比較親近吧。即便如此，最近和菓子製作體驗教室受到外國觀光客歡迎等，以新的形式受到關注的情況也增加了。"},{ja:"季節を目で味わうという楽しみ方は、和菓子ならではのものだ。忙しい毎日の中でも、たまには和菓子を一つ買って、季節の移り変わりを感じてみてはどうだろうか。",zh:"用眼睛品味季節這種享受方式，是和菓子獨有的。即使在忙碌的每一天裡，偶爾買一個和菓子，感受一下季節的變遷，你覺得如何呢？"}],vocab:[{word:"表現",reading:"ひょうげん",meaning:"表現、表達"},{word:"模様",reading:"もよう",meaning:"花紋、圖案"},{word:"想像",reading:"そうぞう",meaning:"想像"},{word:"茶道",reading:"さどう",meaning:"茶道"},{word:"担う",reading:"になう",meaning:"擔負、承擔"},{word:"職人",reading:"しょくにん",meaning:"師傅、工匠"},{word:"工夫",reading:"くふう",meaning:"下工夫、巧思"},{word:"移り変わり",reading:"うつりかわり",meaning:"變遷"}],questions:[{question:"和菓子の名前について、本文の内容に合うものはどれか。",questionZh:"關於和菓子的名字，下列何者符合文章內容？",options:["同じような形でも、色や模様によって名前が変わる","どの店でも必ず同じ名前がつけられている","材料の名前がそのまま使われている","名前は客が自由に決めることができる"]},{question:"和菓子が季節を大切にする理由として、本文で挙げられているものは何か。",questionZh:"文中舉出和菓子重視季節的理由是什麼？",options:["茶道との関わりが深いから","季節によって材料の値段が変わるから","外国人観光客に人気があるから","洋菓子と区別するため"]},{question:"最近の和菓子について、本文で述べられていることはどれか。",questionZh:"關於最近的和菓子，文中提到了什麼？",options:["和菓子作りの体験教室が外国人観光客に人気だ","若い世代が洋菓子より和菓子を好むようになった","和菓子を日常的に食べる人が増えている","和菓子屋の数が大きく増えている"]}]},{id:"n2-r09",title:"空き家が語るもの",titleZh:"空屋訴說的事",topic:"社會",paragraphs:[{ja:"地方を旅していると、雨戸が閉まったままの家や、庭に草が生い茂った家を見かけることが多い。持ち主が亡くなったり、都会に引っ越したりして、誰も住まなくなった「空き家」である。日本では空き家の数が年々増え続けており、大きな社会問題となっている。",zh:"在地方旅行時，常會看到防雨窗一直關著的房子，或是院子裡雜草叢生的房子。這些是因為屋主過世或搬到都市，而變得無人居住的「空屋」。在日本，空屋的數量逐年持續增加，已成為一大社會問題。"},{ja:"空き家が増える背景には、人口の減少と高齢化がある。地方では若者が仕事を求めて都会へ出ていき、残された親の世代が亡くなると、家を引き継ぐ人がいなくなってしまう。また、古い家を壊すには多額の費用がかかるため、そのまま放置されるケースも少なくない。",zh:"空屋增加的背後，有人口減少與高齡化的問題。在地方，年輕人為了找工作前往都市，留下來的父母那一代過世後，就沒有人繼承房子了。另外，拆除老房子需要龐大的費用，因此就這樣被放置不管的案例也不少。"},{ja:"人が住まなくなった家は、想像以上に早く傷んでいく。屋根や壁が壊れて周囲の住民に危険を及ぼしたり、ごみが捨てられたりすることもある。さらに、空き家が並ぶ地域は活気を失い、ますます人が住みたがらなくなるという悪循環に陥りかねない。",zh:"沒人住的房子，損壞的速度比想像中還快。屋頂或牆壁可能損壞而危及周圍居民，也可能被人亂丟垃圾。再者，空屋林立的地區會失去活力，可能陷入越來越沒有人想住的惡性循環。"},{ja:"一方で、空き家を地域の資源として生かそうとする動きも出てきている。古い家を改装してカフェや宿泊施設にしたり、都会から移り住みたい人に安く貸し出したりする試みだ。ある町では、空き家を利用した移住者向けの住宅が評判を呼び、若い家族が少しずつ増え始めているという。",zh:"另一方面，也出現了把空屋當作地方資源加以活用的動向。例如把老房子改裝成咖啡廳或住宿設施，或是便宜租給想從都市移居的人等嘗試。據說在某個小鎮，利用空屋改建的移居者住宅大受好評，年輕家庭開始一點一點地增加。"},{ja:"空き家は、放っておけば地域の負担になるが、使い方次第で町を元気にする力にもなる。古い家に新しい役割を与えることができるかどうかは、そこに住む人々の知恵にかかっているのではないだろうか。",zh:"空屋若放著不管，會成為地方的負擔，但依使用方式不同，也能成為讓城鎮恢復活力的力量。能否賦予老房子新的角色，或許就取決於住在那裡的人們的智慧吧。"}],vocab:[{word:"減少",reading:"げんしょう",meaning:"減少"},{word:"引き継ぐ",reading:"ひきつぐ",meaning:"繼承、接手"},{word:"放置",reading:"ほうち",meaning:"放置不管"},{word:"傷む",reading:"いたむ",meaning:"損壞、腐壞"},{word:"悪循環",reading:"あくじゅんかん",meaning:"惡性循環"},{word:"改装",reading:"かいそう",meaning:"改裝、裝修"},{word:"移住",reading:"いじゅう",meaning:"移居"},{word:"負担",reading:"ふたん",meaning:"負擔"}],questions:[{question:"空き家が増える理由として、本文に書かれていないものはどれか。",questionZh:"下列何者是文中「沒有」提到的空屋增加的理由？",options:["家にかかる税金が高くなったこと","若者が仕事を求めて都会へ出ていくこと","古い家を壊すのに多額の費用がかかること","家を引き継ぐ人がいなくなること"]},{question:"空き家を生かす試みとして、本文で紹介されているものはどれか。",questionZh:"文中介紹了哪一種活用空屋的嘗試？",options:["改装してカフェや宿泊施設にする","壊して子ども向けの公園にする","観光客向けの駐車場にする","学校の教室として使う"]},{question:"筆者の考えに最も近いものはどれか。",questionZh:"下列何者最接近作者的想法？",options:["空き家は使い方次第で町を元気にする力になる","空き家はすべてできるだけ早く壊すべきだ","空き家の問題は国にしか解決できない","空き家は都会にはまったく関係のない問題だ"]}]},{id:"n2-r10",title:"雑草のしたたかな生き方",titleZh:"雜草頑強的生存之道",topic:"自然",paragraphs:[{ja:"道路のひび割れや駐車場のすみなど、ほんのわずかな土しかない場所にも、雑草は元気に生えている。抜いても抜いてもすぐに生えてくるため、庭の手入れをする人にとっては悩みの種だ。しかし、植物の立場から見ると、雑草は驚くほど巧みな生き方をしている。",zh:"在馬路的裂縫或停車場的角落等只有一點點泥土的地方，雜草也長得很有精神。因為拔了又拔還是馬上長出來，對整理庭院的人來說是個煩惱的根源。但是從植物的角度來看，雜草的生存方式巧妙得令人驚訝。"},{ja:"意外なことに、雑草は実は競争に弱い植物だと言われている。森や草原のように多くの植物が育つ場所では、背の高い植物に光をさえぎられ、生き残ることが難しい。そこで雑草は、他の植物が育ちにくい場所、つまり人に踏まれたり、草刈りをされたりする場所を選んで生きるようになったのである。",zh:"令人意外的是，據說雜草其實是不擅長競爭的植物。在森林或草原這種許多植物生長的地方，陽光會被高大的植物遮住，很難存活下來。因此，雜草選擇在其他植物難以生長的地方，也就是會被人踩踏、被除草的地方生存。"},{ja:"例えば、道によく生えているオオバコという草は、踏まれることに強い。葉や茎がやわらかく、踏まれても折れにくいうえ、種は濡れるとねばねばして、人の靴や車のタイヤにくっつく。つまり、踏まれることを利用して、種を遠くまで運んでもらっているのだ。",zh:"例如，常長在路邊的車前草很耐踩踏。它的葉子和莖很柔軟，被踩也不容易折斷，而且種子一沾濕就會變得黏黏的，黏在人的鞋子或車子的輪胎上。也就是說，它利用被踩踏這件事，讓別人幫忙把種子運到遠方。"},{ja:"また、多くの雑草は一度にすべての種を芽生えさせるのではなく、時期をずらして少しずつ芽を出す。そのため、一度草を抜いても、土の中に残った種が次々と芽を出してくる。環境の変化に備えて、危険を分散しているわけである。",zh:"此外，許多雜草不會讓所有種子一次發芽，而是錯開時期一點一點地冒芽。因此，即使拔過一次草，留在土裡的種子也會接二連三地發芽。這是為了應對環境的變化而分散風險。"},{ja:"弱いからこそ、強い者が来ない場所で工夫して生きる。雑草のこうした生き方には、私たち人間が学ぶべき点も多いのではないだろうか。",zh:"正因為弱小，才在強者不會來的地方努力想辦法活下去。雜草這樣的生存方式，或許有很多值得我們人類學習的地方吧。"}],vocab:[{word:"雑草",reading:"ざっそう",meaning:"雜草"},{word:"巧み",reading:"たくみ",meaning:"巧妙"},{word:"競争",reading:"きょうそう",meaning:"競爭"},{word:"踏む",reading:"ふむ",meaning:"踩、踏"},{word:"種",reading:"たね",meaning:"種子"},{word:"備える",reading:"そなえる",meaning:"防備、做準備"},{word:"分散",reading:"ぶんさん",meaning:"分散"}],questions:[{question:"筆者によると、雑草が道や駐車場に生えているのはなぜか。",questionZh:"根據作者的說法，雜草為什麼會長在路邊或停車場？",options:["競争に弱く、他の植物が育ちにくい場所を選んだから","道路の土には栄養がとても多いから","人間がわざと種をまいたから","強い光が苦手で暗い場所を好むから"]},{question:"オオバコについて、本文の内容に合うものはどれか。",questionZh:"關於車前草，下列何者符合文章內容？",options:["踏まれることを利用して種を運んでもらう","背が高く、他の植物の光をさえぎる","種は乾くとねばねばする","踏まれるとすぐに枯れてしまう"]},{question:"雑草が時期をずらして芽を出すのはなぜか。",questionZh:"雜草為什麼要錯開時期發芽？",options:["環境の変化に備えて危険を分散するため","ほかの雑草より早く大きくなるため","種の数を少しでも減らすため","人に見つからないようにするため"]}]},{id:"n2-r11",title:"雨の日の三本の傘",titleZh:"雨天的三把傘",topic:"推理",paragraphs:[{ja:"激しい雨が降る午後、探偵の森川のもとに、資産家の大野から依頼があった。書斎の机に置いていた大切な契約書がなくなったというのだ。大野は二時から三時まで昼寝をしていて、その間に何者かが書斎に入ったらしい。森川が大野の家に着いたのは、四時少し前のことだった。",zh:"某個下著大雨的午後，偵探森川接到富豪大野的委託。大野說，放在書房桌上的重要合約書不見了。大野從兩點到三點在睡午覺，似乎有人在這段期間進了書房。森川抵達大野家時，是快四點的時候。"},{ja:"その日、大野の家を訪れたのは三人だった。甥の健太は「僕が来たのは三時半です。叔父さんが起きた後ですよ」と言った。秘書の松井は「私は一時に来て、ずっと台所で書類の整理をしていました」と答えた。近所の医者の石田は「三時四十分ごろ、診察に来たばかりです」と話した。",zh:"那天造訪大野家的有三個人。外甥健太說：「我是三點半來的，是在舅舅起床之後喔。」秘書松井回答：「我一點就來了，一直在廚房整理文件。」附近的醫生石田說：「我三點四十分左右才剛來看診。」"},{ja:"森川は玄関に置かれた三本の傘を見た。松井の傘はすっかり乾いていた。石田の傘からは、まだ水が流れ落ちていた。ところが、健太の傘は少し湿っている程度で、ほとんど乾きかけていた。森川は大野に尋ねた。「雨はいつから降っていますか。」「昼過ぎからずっと、強く降り続けていますよ。」",zh:"森川看了看放在玄關的三把傘。松井的傘已經完全乾了。石田的傘還在往下滴水。然而，健太的傘只是有點濕，幾乎快乾了。森川問大野：「雨是從什麼時候開始下的？」「從中午過後就一直下得很大。」"},{ja:"森川は健太の方を向いた。「健太さん、あなたは三時半に来たと言いましたね。しかし、この強い雨の中を歩いてきたばかりなら、あなたの傘も石田先生の傘と同じように濡れているはずです。ほとんど乾いているということは、あなたはもっと前、おそらく叔父さんが昼寝をしていたころには、すでにこの家にいたのではありませんか。」",zh:"森川轉向健太。「健太先生，您說您是三點半來的吧。但是，如果您才剛在這場大雨中走過來，您的傘應該也會和石田醫生的傘一樣濕才對。傘幾乎已經乾了，就表示您更早之前，恐怕在舅舅睡午覺的時候，就已經在這個家裡了吧？」"},{ja:"健太はしばらく黙っていたが、やがて契約書を鞄から取り出した。借金に困り、叔父の財産に関する書類を持ち出そうとしたのだという。大野は深いため息をついたが、警察には知らせず、もう一度甥とよく話し合うことにした。",zh:"健太沉默了一會兒，最後從包包裡拿出了合約書。據說他是因為欠債困擾，才想把有關舅舅財產的文件帶出去。大野深深嘆了一口氣，但沒有報警，決定再和外甥好好談一談。"}],vocab:[{word:"依頼",reading:"いらい",meaning:"委託、請求"},{word:"書斎",reading:"しょさい",meaning:"書房"},{word:"契約書",reading:"けいやくしょ",meaning:"合約書"},{word:"甥",reading:"おい",meaning:"外甥、姪子（男）"},{word:"秘書",reading:"ひしょ",meaning:"秘書"},{word:"乾く",reading:"かわく",meaning:"乾燥、變乾"},{word:"湿る",reading:"しめる",meaning:"潮濕、受潮"},{word:"借金",reading:"しゃっきん",meaning:"欠債、借款"}],questions:[{question:"契約書が持ち出されたのは、いつだと考えられるか。",questionZh:"合約書被拿走的時間，推測是什麼時候？",options:["二時から三時の間","一時より前","三時半から四時の間","昼過ぎより前"]},{question:"森川が見たとき、石田の傘はどんな状態だったか。",questionZh:"森川看到時，石田的傘是什麼狀態？",options:["まだ水が流れ落ちていた","すっかり乾いていた","少し湿っている程度だった","骨が折れて壊れていた"]},{question:"犯人は誰で、何が手がかりになったか。",questionZh:"犯人是誰？什麼成為了線索？",options:["健太で、傘がほとんど乾きかけていたこと","松井で、傘がすっかり乾いていたこと","石田で、傘から水が流れ落ちていたこと","大野で、昼寝をしていたと言ったこと"]}]},{id:"n2-r12",title:"革のケースの中身",titleZh:"皮套裡的東西",topic:"推理",paragraphs:[{ja:"大学で心理学を教える小林先生は、ちょっとした謎を解くのが得意なことで知られている。ある日の昼、先生は翌日のゼミで使う古いカメラを、茶色い革のケースに入れたまま教室の机に置いた。そして、そこにいた三人の学生に「大切な物だから、触らないように」と伝えて研究室に戻った。",zh:"在大學教心理學的小林老師，以擅長解開小謎團而聞名。某天中午，老師把隔天專題課要用的舊相機，連同棕色皮套一起放在教室的桌上。然後告訴在場的三位學生「這是很重要的東西，不要碰」，就回研究室去了。"},{ja:"ところが、夕方五時に先生が教室に戻ると、ケースは机の上にあったが、中のカメラだけが消えていた。三人に聞くと、それぞれ午後四時ごろに別の用事で教室を離れたという。教室には鍵がかかっていなかったので、三人以外の誰かが入った可能性もないとは言えない。",zh:"然而，傍晚五點老師回到教室時，皮套還在桌上，裡面的相機卻不見了。問了三個人，他們說各自在下午四點左右因為別的事離開了教室。教室沒有上鎖，所以也不能說沒有三人以外的人進來的可能性。"},{ja:"小林先生は一人ずつ話を聞いた。佐々木は「図書館でレポートを書いていました。ケースには一度も触っていません」と言った。原田は「食堂で友達とお茶を飲んでいました。それにしても、あんな黒くて小さいカメラ、誰が欲しがるんでしょうね」と首をかしげた。山口は「アルバイトの面接に行っていました。中にどんなカメラが入っていたのかも知りません」と答えた。",zh:"小林老師一個一個詢問。佐佐木說：「我在圖書館寫報告。我一次也沒碰過皮套。」原田歪著頭說：「我在餐廳和朋友喝茶。話說回來，那種又黑又小的相機，誰會想要呢？」山口回答：「我去參加打工的面試了。我連裡面裝的是什麼樣的相機都不知道。」"},{ja:"三人の話を聞き終えると、小林先生は原田に向かって穏やかに言った。「原田君、あのカメラはずっと茶色い革のケースに入っていて、私は一度も中から出していない。君たちは誰も中身を見ていないはずだ。それなのに、どうして黒くて小さいカメラだと知っているのかな。」",zh:"聽完三人的話後，小林老師對原田平靜地說：「原田同學，那台相機一直裝在棕色皮套裡，我一次都沒有拿出來過。你們應該沒有人看過裡面的東西才對。可是，你為什麼會知道那是一台又黑又小的相機呢？」"},{ja:"原田はしばらく言葉に詰まっていたが、やがて正直に話し始めた。古いカメラに興味があり、少しだけ見るつもりでケースを開けたところ、うっかり落として傷をつけてしまった。怒られるのが怖くなり、自分のロッカーに隠したのだという。先生は笑って、「正直に言ってくれてよかった」と言った。",zh:"原田一時語塞，但不久後便老實地說了出來。他對舊相機很感興趣，打算只看一下就打開了皮套，結果不小心摔到而留下了刮痕。他害怕被罵，就把相機藏在自己的置物櫃裡了。老師笑著說：「你肯老實說出來真是太好了。」"}],vocab:[{word:"研究室",reading:"けんきゅうしつ",meaning:"研究室"},{word:"翌日",reading:"よくじつ",meaning:"隔天、第二天"},{word:"可能性",reading:"かのうせい",meaning:"可能性"},{word:"面接",reading:"めんせつ",meaning:"面試"},{word:"穏やか",reading:"おだやか",meaning:"平靜、溫和"},{word:"詰まる",reading:"つまる",meaning:"（言語）卡住、塞住"},{word:"傷",reading:"きず",meaning:"傷痕、刮痕"},{word:"隠す",reading:"かくす",meaning:"隱藏"}],questions:[{question:"小林先生が教室に置いたとき、カメラはどんな状態だったか。",questionZh:"小林老師把相機放在教室時，相機是什麼狀態？",options:["茶色い革のケースに入っていた","ケースから出して机の上に置かれていた","先生のかばんの中に入っていた","鍵のかかった棚にしまわれていた"]},{question:"山口は、午後に何をしていたと言ったか。",questionZh:"山口說他下午在做什麼？",options:["アルバイトの面接に行っていた","図書館でレポートを書いていた","食堂で友達とお茶を飲んでいた","研究室で先生を待っていた"]},{question:"小林先生が原田を疑ったのはなぜか。",questionZh:"小林老師為什麼懷疑原田？",options:["誰も見ていないはずのカメラの色と大きさを知っていたから","食堂にいたことを証明できなかったから","ケースに原田の指紋が残っていたから","一番最後に教室を出たから"]}]},{id:"n2-r13",title:"家計簿が教えてくれたこと",titleZh:"記帳教會我的事",topic:"生活",paragraphs:[{ja:"去年の春、私は初めて家計簿をつけ始めた。きっかけは、毎月給料日の前になると、なぜか財布の中がほとんど空になっていることだった。特に大きな買い物をした覚えはないのに、お金はいったいどこへ消えてしまうのか。その答えを知りたいと思ったのである。",zh:"去年春天，我第一次開始記帳。契機是每個月一到發薪日前，錢包裡不知為何總是幾乎空空如也。我並不記得自己買過什麼大件的東西，錢究竟消失到哪裡去了呢？我想知道這個答案。"},{ja:"最初の一か月は、レシートをもらうたびに金額を手帳に書き写した。面倒に感じることもあったが、月末に合計してみて驚いた。コンビニで買うコーヒーやお菓子、なんとなく立ち寄った店での小さな買い物が、合わせると一万円を超えていたのだ。一回一回は数百円にすぎないため、お金を使ったという意識がほとんどなかったのである。",zh:"第一個月，我每次拿到收據，就把金額抄到手帳上。雖然有時覺得麻煩，但到了月底加總一看，我嚇了一跳。在便利商店買的咖啡和零食，以及隨意順路走進的店裡的小額消費，加起來竟然超過了一萬日圓。因為每一次都只不過幾百日圓，所以幾乎沒有「花了錢」的意識。"},{ja:"とはいえ、私はこうした出費をすべてやめようとは思わなかった。仕事の合間に飲むコーヒーは、私にとって大切な息抜きでもあるからだ。そこで、本当に必要なものとそうでないものを分けて考えることにした。コーヒーは続けるが、空腹でもないのに買っていたお菓子はやめる。それだけで、翌月の支出はかなり減った。",zh:"話雖如此，我並沒有打算把這些開銷全部戒掉。因為工作空檔喝的咖啡，對我來說也是重要的喘口氣時間。於是，我決定把真正需要的東西和不需要的東西分開來考慮。咖啡繼續喝，但明明不餓卻照買的零食就戒掉。光是這樣，下個月的支出就減少了不少。"},{ja:"家計簿をつけて気づいたのは、お金の使い方にはその人の生活がそのまま表れるということだ。疲れている週ほど外食や買い物が増え、気持ちに余裕のある週は自分で料理をしている。数字を眺めていると、自分の心の状態まで見えてくるようで興味深い。",zh:"記帳後我發現，一個人花錢的方式，會原原本本地反映出那個人的生活。越是疲累的那一週，外食和購物就越多；心情上有餘裕的那一週，則會自己下廚。看著這些數字，彷彿連自己的心理狀態都看得見，十分有趣。"},{ja:"節約のために始めた家計簿だが、今では自分を知るための記録になっている。お金を管理することは、結局、自分の暮らし方を見直すことにつながるのだろう。",zh:"雖然是為了節省開支而開始記帳，但現在它已成為了解自己的紀錄。管理金錢，說到底，或許也就是在重新審視自己的生活方式吧。"}],vocab:[{word:"家計簿",reading:"かけいぼ",meaning:"家庭收支簿、記帳本"},{word:"きっかけ",reading:"きっかけ",meaning:"契機、起因"},{word:"給料日",reading:"きゅうりょうび",meaning:"發薪日"},{word:"意識",reading:"いしき",meaning:"意識、自覺"},{word:"出費",reading:"しゅっぴ",meaning:"開銷、花費"},{word:"息抜き",reading:"いきぬき",meaning:"喘口氣、休息放鬆"},{word:"支出",reading:"ししゅつ",meaning:"支出"},{word:"節約",reading:"せつやく",meaning:"節約、節省"}],questions:[{question:"筆者が家計簿をつけ始めたきっかけは何か。",questionZh:"作者開始記帳的契機是什麼？",options:["給料日の前になると財布がほとんど空になっていたこと","大きな買い物をして貯金がなくなってしまったこと","家族から節約するように強く言われたこと","給料が前の年よりも大幅に減ってしまったこと"]},{question:"筆者に「お金を使ったという意識がほとんどなかった」のはなぜか。",questionZh:"作者為什麼幾乎沒有「花了錢」的意識？",options:["一回の買い物が数百円にすぎなかったから","レシートをもらわずに買い物をしていたから","買い物の代金を家族が払っていたから","コンビニにはほとんど行かなかったから"]},{question:"筆者は家計簿についてどのように考えているか。",questionZh:"作者對記帳有什麼樣的看法？",options:["自分の暮らし方を見直すことにつながるものだ","小さな出費をすべてなくすための道具だ","面倒なので長く続けるべきものではない","お金に余裕のない人だけがつければよいものだ"]}]},{id:"n2-r14",title:"風呂敷の知恵",titleZh:"包袱巾的智慧",topic:"文化",paragraphs:[{ja:"風呂敷という一枚の四角い布をご存じだろうか。日本では昔から、物を包んだり運んだりするのに使われてきた。名前の由来には諸説あるが、江戸時代に銭湯へ行く人々が、脱いだ着物を包むのに使ったことから広まったと言われている。",zh:"你知道「風呂敷」這種一塊四方形的布嗎？在日本，它自古以來就被用來包裹或搬運物品。關於名稱的由來有各種說法，據說是因為江戶時代去錢湯的人們用它來包脫下的和服，才普及開來的。"},{ja:"風呂敷の最大の特徴は、包む物の形や大きさを選ばないことだ。箱はもちろん、瓶や丸い果物のように包みにくい物でも、結び方を工夫すればきれいに包むことができる。使わないときは小さく畳んでかばんに入れておけるので、場所も取らない。一枚の布がこれほど多くの役割を果たすのは、驚くべきことである。",zh:"風呂敷最大的特色，是不挑所包物品的形狀和大小。箱子自不用說，就連瓶子或圓形水果這類不好包的東西，只要在綁法上下點工夫，也能包得很漂亮。不用的時候可以摺小放進包包裡，也不佔空間。一塊布能發揮這麼多作用，實在令人驚訝。"},{ja:"しかし、紙袋やビニール袋が普及するにつれて、風呂敷を日常的に使う人は少なくなった。今では、結婚式でお祝いの品を渡すときなど、改まった場面で見かける程度かもしれない。若い人の中には、結び方を知らないという人も多いだろう。",zh:"然而，隨著紙袋和塑膠袋的普及，日常使用風呂敷的人變少了。如今，或許只有在婚禮上送賀禮等正式場合才會看到。年輕人當中，應該也有很多人不知道怎麼綁吧。"},{ja:"ところが最近、環境への関心の高まりとともに、風呂敷が再び注目を集めている。何度でも繰り返し使えるため、ごみを減らすことができるからだ。おしゃれな柄のものも増え、エコバッグの代わりに買い物に持っていく人や、海外へのお土産として選ぶ人もいるという。",zh:"不過最近，隨著人們對環境越來越關心，風呂敷再度受到矚目。因為它可以反覆使用許多次，所以能減少垃圾。花紋時髦的款式也增加了，據說有人用它代替環保袋去購物，也有人選它當作帶到國外的伴手禮。"},{ja:"古い道具だと思われがちな風呂敷だが、そこには物を大切にし、無駄を出さないという考え方が込められている。昔の人の知恵は、現代の暮らしの中でも十分に生かせるのではないだろうか。",zh:"風呂敷常被認為是老舊的工具，但其中蘊含著珍惜物品、不製造浪費的想法。前人的智慧，在現代生活中不也能充分活用嗎？"}],vocab:[{word:"由来",reading:"ゆらい",meaning:"由來、來歷"},{word:"諸説",reading:"しょせつ",meaning:"各種說法"},{word:"畳む",reading:"たたむ",meaning:"摺疊"},{word:"役割",reading:"やくわり",meaning:"作用、角色"},{word:"普及",reading:"ふきゅう",meaning:"普及"},{word:"改まる",reading:"あらたまる",meaning:"正式、鄭重"},{word:"柄",reading:"がら",meaning:"花紋、圖案"},{word:"知恵",reading:"ちえ",meaning:"智慧"}],questions:[{question:"本文によると、風呂敷の特徴として正しいものはどれか。",questionZh:"根據本文，下列何者是風呂敷的特色？",options:["包む物の形や大きさを選ばないこと","四角い箱しか包むことができないこと","一度使ったら捨てなければならないこと","畳めないので持ち歩くのに不便なこと"]},{question:"風呂敷が再び注目を集めているのはなぜか。",questionZh:"風呂敷為什麼再度受到矚目？",options:["繰り返し使えて、ごみを減らせるから","紙袋やビニール袋よりも値段が安いから","結婚式で使うことが決まりになったから","学校で結び方を教えるようになったから"]},{question:"筆者が最も言いたいことは何か。",questionZh:"作者最想表達的是什麼？",options:["風呂敷に込められた昔の知恵は、今の暮らしにも生かせる","風呂敷は古い道具なので、もう使う必要はない","風呂敷は改まった場面だけで使うべきものだ","風呂敷の結び方は難しいので、覚えなくてもよい"]}]},{id:"n2-r15",title:"食品ロスを減らすために",titleZh:"為了減少食物浪費",topic:"社會",paragraphs:[{ja:"まだ食べられるのに捨てられてしまう食品を「食品ロス」と呼ぶ。日本では、その量が年間数百万トンにものぼるといわれている。世界には十分に食べられない人々が大勢いることを考えると、これは見過ごすことのできない問題である。",zh:"明明還能吃卻被丟掉的食品，稱為「食品損耗（食物浪費）」。據說在日本，其數量每年高達數百萬噸。想到世界上還有許多人吃不飽，這是一個不容忽視的問題。"},{ja:"食品ロスの原因は、店や工場だけにあるわけではない。実は、その半分近くは一般の家庭から出ているという。買いすぎて使い切れなかった野菜、作りすぎて残してしまった料理、冷蔵庫の奥で賞味期限が切れていた食品など、思い当たる人も多いのではないだろうか。",zh:"食物浪費的原因並不只在商店和工廠。其實據說將近一半是來自一般家庭。買太多而沒能用完的蔬菜、做太多而剩下的料理、在冰箱深處過了賞味期限的食品等等，應該有很多人心裡有數吧。"},{ja:"ここで注意したいのは、賞味期限と消費期限の違いである。消費期限が「安全に食べられる期限」を示すのに対し、賞味期限は「おいしく食べられる期限」を示している。つまり、賞味期限を少し過ぎたからといって、すぐに食べられなくなるわけではないのだ。この違いを知らないために、まだ食べられる食品を捨ててしまう人も少なくない。",zh:"在此要特別注意的，是賞味期限和消費期限的差別。消費期限表示的是「可以安全食用的期限」，相對地，賞味期限表示的是「可以美味食用的期限」。也就是說，並不是賞味期限稍微過了，就馬上不能吃了。因為不知道這個差別，而把還能吃的食品丟掉的人也不少。"},{ja:"最近では、社会全体でこの問題に取り組む動きも広がっている。期限が近い商品を値引きして売るスーパーや、余った食品を必要とする施設に届ける活動などがその例だ。一方で、私たち一人一人にもできることはある。買い物の前に冷蔵庫の中身を確認し、必要な分だけを買うことである。",zh:"最近，整個社會投入解決這個問題的行動也逐漸擴大。例如將快到期的商品打折出售的超市，以及把多餘的食品送到有需要的機構的活動等。另一方面，我們每個人也有能做的事，那就是購物前先確認冰箱裡有什麼，只買需要的量。"},{ja:"食べ物を無駄にしないことは、決して特別なことではない。毎日の小さな心がけの積み重ねこそが、大きな問題の解決につながるのだと思う。",zh:"不浪費食物絕不是什麼特別的事。我認為，正是日常點滴用心的累積，才能促成大問題的解決。"}],vocab:[{word:"見過ごす",reading:"みすごす",meaning:"忽視、放過"},{word:"思い当たる",reading:"おもいあたる",meaning:"想到、心裡有數"},{word:"賞味期限",reading:"しょうみきげん",meaning:"賞味期限（最佳食用期限）"},{word:"消費期限",reading:"しょうひきげん",meaning:"消費期限（安全食用期限）"},{word:"取り組む",reading:"とりくむ",meaning:"致力於、處理"},{word:"値引き",reading:"ねびき",meaning:"減價、打折"},{word:"施設",reading:"しせつ",meaning:"機構、設施"},{word:"積み重ね",reading:"つみかさね",meaning:"累積"}],questions:[{question:"本文によると、食品ロスの半分近くはどこから出ているか。",questionZh:"根據本文，將近一半的食物浪費來自哪裡？",options:["一般の家庭から","食品を作る工場から","スーパーなどの店から","レストランや食堂から"]},{question:"賞味期限について、本文の内容に合うものはどれか。",questionZh:"關於賞味期限，下列何者符合本文內容？",options:["少し過ぎても、すぐに食べられなくなるわけではない","安全に食べられる期限を示している","過ぎたら、すぐに捨てなければならない","消費期限と同じ意味で使われている"]},{question:"筆者が、私たち一人一人にできることとして挙げているのは何か。",questionZh:"作者舉出我們每個人能做的事是什麼？",options:["冷蔵庫の中身を確認して、必要な分だけ買うこと","期限が近い商品だけを選んで買うこと","食べきれない料理を近所の人に分けること","賞味期限が切れた食品はすぐに捨てること"]}]},{id:"n2-r16",title:"移動販売車が運ぶもの",titleZh:"行動販售車載來的東西",topic:"社會",paragraphs:[{ja:"毎週火曜日の午前十時になると、山あいの小さな集落に軽快な音楽が流れてくる。食料品や日用品を積んだ移動販売車がやって来た合図だ。音楽を聞きつけたお年寄りたちが次々と家から出てきて、車の周りに集まる。",zh:"每週二上午十點一到，山間的小村落就會傳來輕快的音樂。這是載著食品和日用品的行動販售車到來的信號。聽到音樂的老人們一個接一個從家裡走出來，聚集在車子周圍。"},{ja:"この集落にはかつて小さな商店が一軒あったが、十年ほど前に閉店してしまった。一番近いスーパーまでは、車で三十分以上かかる。車を運転しない高齢者にとって、毎日の買い物は大きな負担である。こうした日常の買い物に困っている人々は「買い物弱者」と呼ばれ、地方を中心に増えているという。",zh:"這個村落以前有一間小商店，但大約十年前就關門了。到最近的超市，開車也要三十分鐘以上。對不開車的高齡者來說，每天的購物是很大的負擔。像這樣在日常購物上有困難的人被稱為「購物弱勢族群」，據說以地方為中心正在增加。"},{ja:"移動販売車は、そのような人々にとって欠かせない存在になっている。肉や魚、野菜といった生鮮食品を自分の目で見て選べるのがありがたいと、利用者は口をそろえる。また、運転手は一人一人の好みを覚えていて、頼まれた品物を次に来るときまでに用意しておくこともあるそうだ。",zh:"行動販售車對這樣的人們來說，已成為不可或缺的存在。使用者異口同聲地表示，能親眼挑選肉、魚、蔬菜等生鮮食品，真的很感激。此外，據說司機記得每個人的喜好，有時還會在下次來之前先準備好被託付的商品。"},{ja:"しかし、移動販売車が運んでいるのは品物だけではない。ある女性は「ここで近所の人と話すのが楽しみなの」と笑う。一人暮らしの高齢者にとっては、人と言葉を交わす貴重な機会なのだ。いつも来る人の姿が見えないと、運転手が家まで様子を見に行くこともあり、地域の見守りの役割も果たしている。",zh:"然而，行動販售車運送的不只是商品。一位女性笑著說：「在這裡和鄰居聊天是我的樂趣。」對獨居的高齡者來說，這是與人交談的寶貴機會。如果沒看到平常會來的人，司機有時還會到家裡去看看情況，也發揮了守護地區的作用。"},{ja:"便利さだけを考えれば、インターネットで注文する方が効率的かもしれない。それでも、顔を合わせて買い物をすることには、数字では測れない価値があるのではないだろうか。",zh:"如果只考慮便利性，在網路上訂購或許更有效率。即使如此，面對面購物，難道不是有著無法用數字衡量的價值嗎？"}],vocab:[{word:"集落",reading:"しゅうらく",meaning:"村落、聚落"},{word:"合図",reading:"あいず",meaning:"信號、暗號"},{word:"負担",reading:"ふたん",meaning:"負擔"},{word:"欠かせない",reading:"かかせない",meaning:"不可或缺的"},{word:"生鮮食品",reading:"せいせんしょくひん",meaning:"生鮮食品"},{word:"口をそろえる",reading:"くちをそろえる",meaning:"異口同聲"},{word:"貴重",reading:"きちょう",meaning:"寶貴、珍貴"},{word:"見守り",reading:"みまもり",meaning:"守護、照看"}],questions:[{question:"この集落の高齢者にとって、買い物が大きな負担になっているのはなぜか。",questionZh:"對這個村落的高齡者來說，購物為什麼是很大的負擔？",options:["近くに店がなく、スーパーまで車で三十分以上かかるから","集落の商店で売っている品物の値段がとても高いから","移動販売車が一か月に一度しか来てくれないから","スーパーがいつも混んでいて、長い時間待たされるから"]},{question:"「移動販売車が運んでいるのは品物だけではない」とあるが、品物のほかに何を運んでいるか。",questionZh:"文中提到「行動販售車運送的不只是商品」，除了商品之外還運送了什麼？",options:["人と話す機会や、地域を見守る安心","遠くの町で起きた出来事の情報","役所から届いた郵便物や書類","病院へ通うお年寄りの家族"]},{question:"筆者の考えに最も近いものはどれか。",questionZh:"下列何者最接近作者的想法？",options:["顔を合わせて買い物をすることには、数字では測れない価値がある","インターネットで注文する方が、移動販売車よりも価値がある","移動販売車は効率が悪いので、ほかの方法に変えるべきだ","高齢者は店の多い町に引っ越して、自分で買い物をするべきだ"]}]},{id:"n2-r17",title:"川に戻ったホタル",titleZh:"回到河川的螢火蟲",topic:"自然",paragraphs:[{ja:"初夏の夜、暗い川辺に小さな光がふわりと浮かび上がる。ホタルである。かつて日本では、ホタルは夏の夜にどこでも見られる身近な虫だった。しかし、川の水が汚れるにつれて、その姿は多くの地域から消えていった。",zh:"初夏的夜晚，昏暗的河邊輕飄飄地浮現出小小的光點。那就是螢火蟲。過去在日本，螢火蟲是夏夜裡隨處可見、貼近生活的昆蟲。然而，隨著河水變髒，牠們的身影從許多地區消失了。"},{ja:"ホタルが生きていくためには、きれいな水が欠かせない。ゲンジボタルの幼虫は一年近くを川の中で過ごし、カワニナという小さな貝を食べて育つ。そのため、水が汚れてカワニナがいなくなれば、ホタルも生きていけなくなる。また、川岸がコンクリートで固められると、幼虫が土にもぐってさなぎになる場所も失われてしまう。",zh:"螢火蟲要生存，乾淨的水是不可或缺的。源氏螢的幼蟲有將近一年的時間待在河裡，靠吃一種叫做「川蜷」的小螺貝長大。因此，如果水變髒、川蜷消失，螢火蟲也就無法生存。此外，河岸若被水泥封住，幼蟲鑽進土裡化蛹的地方也會跟著消失。"},{ja:"ある町では、二十年ほど前から住民がホタルを呼び戻す活動を続けてきた。川のごみを拾い、家庭からの排水を減らす工夫をし、川岸には土や草を残すようにした。最初の数年は、ほとんど成果が見られなかったという。それでもあきらめずに続けた結果、十年目の夏、ついに川に光が戻ってきたのである。",zh:"某個小鎮從大約二十年前開始，居民就持續進行召回螢火蟲的活動。他們撿拾河裡的垃圾，設法減少家庭排放的廢水，並在河岸保留泥土和草。據說最初幾年幾乎看不到成果。即使如此，他們仍不放棄地持續下去，結果在第十年的夏天，光芒終於回到了河上。"},{ja:"興味深いのは、ホタルが戻ったことで、ほかの生き物も増えたことだ。小さな魚やトンボが見られるようになり、川で遊ぶ子どもたちの姿も戻ってきた。ホタルは、川の環境が健全であるかどうかを示す目印のような存在だと言えるだろう。",zh:"有趣的是，螢火蟲回來之後，其他生物也增加了。開始能看到小魚和蜻蜓，在河邊玩耍的孩子們的身影也回來了。螢火蟲可以說是一種標誌般的存在，顯示河川環境是否健全。"},{ja:"一度失われた自然を取り戻すには、長い時間と根気が必要だ。だが、人々の努力によって再びともったあの光は、自然と人間が共に生きていけることを教えてくれているように思える。",zh:"要找回一度失去的自然，需要漫長的時間和毅力。但是，靠著人們的努力再次亮起的那道光，似乎在告訴我們，自然與人類是能夠共存的。"}],vocab:[{word:"身近",reading:"みぢか",meaning:"身邊、貼近生活"},{word:"幼虫",reading:"ようちゅう",meaning:"幼蟲"},{word:"呼び戻す",reading:"よびもどす",meaning:"召回、喚回"},{word:"排水",reading:"はいすい",meaning:"排水、廢水"},{word:"成果",reading:"せいか",meaning:"成果"},{word:"健全",reading:"けんぜん",meaning:"健全、健康"},{word:"目印",reading:"めじるし",meaning:"標誌、記號"},{word:"根気",reading:"こんき",meaning:"耐心、毅力"}],questions:[{question:"ホタルが多くの地域から姿を消した理由として、本文の内容に合うものはどれか。",questionZh:"關於螢火蟲從許多地區消失的原因，下列何者符合本文內容？",options:["川の水が汚れ、えさになる貝がいなくなったから","夏の夜の気温が年々高くなっていったから","子どもたちがホタルを捕まえすぎたから","川辺に明るい街灯がたくさん作られたから"]},{question:"町の住民がホタルを呼び戻すために行ったこととして、正しいものはどれか。",questionZh:"下列何者是小鎮居民為了召回螢火蟲所做的事？",options:["川岸に土や草を残すようにした","川岸をコンクリートで固めた","ほかの地域からホタルを運んできた","川に魚やトンボを放した"]},{question:"筆者は、ホタルをどのような存在だと述べているか。",questionZh:"作者說螢火蟲是什麼樣的存在？",options:["川の環境が健全かどうかを示す目印","川の水をきれいにしてくれる生き物","ほかの生き物を川から追い出す生き物","一年中いつでも見られる身近な虫"]}]},{id:"n2-r18",title:"あくびはなぜうつるのか",titleZh:"為什麼哈欠會傳染",topic:"科學",paragraphs:[{ja:"会議中、隣の人が大きなあくびをしたのを見て、つられて自分もあくびをしてしまった。そんな経験はないだろうか。あくびは眠いときや退屈なときに出るものだと思われがちだが、他人のあくびを見たり、その声を聞いたりしただけで出ることもある。いったいなぜ、あくびはうつるのだろうか。",zh:"開會時，看到旁邊的人打了個大哈欠，自己也跟著打了哈欠。你有過這樣的經驗嗎？哈欠常被認為是在想睡或無聊時才會出現，但有時光是看到別人打哈欠，或聽到那個聲音，也會跟著打。哈欠究竟為什麼會傳染呢？"},{ja:"そもそも、あくびが何のために出るのかについては、まだはっきりとはわかっていない。以前は、体の中に酸素を取り入れるためだと考えられていたが、現在ではこの説を疑問視する研究者も多い。最近では、大きく口を開けて空気を吸い込むことで脳の温度を下げ、頭をすっきりさせる働きがあるという説が注目されている。",zh:"說起來，哈欠究竟是為了什麼而出現，目前仍未完全弄清楚。以前人們認為是為了把氧氣吸入體內，但現在也有許多研究者對這個說法抱持懷疑。最近，有一種說法受到矚目：藉由張大嘴巴吸入空氣，可以降低大腦的溫度，讓頭腦變得清醒。"},{ja:"では、あくびがうつる理由はどうだろうか。有力な説の一つは、他人の気持ちを感じ取る「共感」の能力と関係があるというものだ。ある研究では、知らない人よりも家族や親しい友人のあくびの方がうつりやすいという結果が出ている。相手との心の距離が近いほど、無意識のうちに相手と同じ行動をとってしまうのかもしれない。",zh:"那麼，哈欠會傳染的原因又是什麼呢？有力的說法之一，是它與感受他人心情的「共感（同理心）」能力有關。某項研究的結果顯示，比起陌生人，家人或親密朋友的哈欠更容易傳染。或許和對方心理上的距離越近，就越會在不知不覺中做出和對方相同的行為。"},{ja:"さらに興味深いことに、あくびのうつり方は年齢によっても異なるらしい。生まれたばかりの赤ちゃんは他人のあくびにほとんど反応しないが、成長して他人の気持ちが理解できるようになるにつれて、あくびがうつるようになるという。これも、あくびと共感との結びつきを示すものと考えられている。",zh:"更有趣的是，哈欠的傳染方式似乎也因年齡而異。據說剛出生的嬰兒對他人的哈欠幾乎沒有反應，但隨著成長、逐漸能理解他人的心情，就會開始被哈欠傳染。這一點也被認為顯示了哈欠與同理心之間的關聯。"},{ja:"何気ないあくび一つにも、人と人とのつながりが隠されているとすれば面白い。次に誰かのあくびがうつったときは、それだけ相手に心を寄せている証拠だと思ってみてはどうだろうか。",zh:"如果一個不經意的哈欠裡，也隱藏著人與人之間的連結，那就很有意思了。下次被別人的哈欠傳染時，不妨把它想成是自己對對方有所關心的證據吧。"}],vocab:[{word:"退屈",reading:"たいくつ",meaning:"無聊"},{word:"酸素",reading:"さんそ",meaning:"氧氣"},{word:"疑問視",reading:"ぎもんし",meaning:"懷疑、存疑"},{word:"有力",reading:"ゆうりょく",meaning:"有力的"},{word:"共感",reading:"きょうかん",meaning:"同理心、共鳴"},{word:"無意識",reading:"むいしき",meaning:"無意識、不知不覺"},{word:"異なる",reading:"ことなる",meaning:"不同"},{word:"何気ない",reading:"なにげない",meaning:"不經意的、若無其事的"}],questions:[{question:"最近注目されている、あくびの働きについての説はどれか。",questionZh:"最近受到矚目的、關於哈欠作用的說法是哪一個？",options:["脳の温度を下げ、頭をすっきりさせる","体の中に酸素を取り入れる","眠りを深くして、体の疲れを取る","周りの人に自分の眠気を知らせる"]},{question:"本文で紹介されている研究によると、あくびがうつりやすいのはどのような場合か。",questionZh:"根據本文介紹的研究，在什麼情況下哈欠比較容易傳染？",options:["家族や親しい友人のあくびを見た場合","知らない人のあくびを見た場合","生まれたばかりの赤ちゃんのあくびを見た場合","大きな声であくびをする人を見た場合"]},{question:"筆者によると、誰かのあくびがうつるのは、どのようなことの表れだと考えられるか。",questionZh:"根據作者的說法，被某人的哈欠傳染，可以被認為是什麼的表現？",options:["相手に共感し、心を寄せていること","体の中の酸素が足りなくなっていること","相手の話を退屈だと感じていること","その場の空気が悪くなっていること"]}]},{id:"n2-r19",title:"祖父の眼鏡はどこへ",titleZh:"爺爺的眼鏡去哪了",topic:"推理",paragraphs:[{ja:"日曜日の夕方、中学生の葵が祖父の家を訪ねると、祖父は困った顔で部屋の中を歩き回っていた。「眼鏡が見つからないんだ。家の中はもう全部探したんだがね。」祖父は細かい字を読むときだけ眼鏡をかけるので、普段はシャツの胸ポケットに入れて持ち歩いているという。",zh:"星期日傍晚，國中生葵去拜訪爺爺家時，爺爺正一臉困擾地在房間裡走來走去。「我找不到眼鏡。家裡已經全部找過了。」據說爺爺只有在看小字時才戴眼鏡，所以平常都放在襯衫胸前的口袋裡隨身攜帶。"},{ja:"葵は、祖父に今日一日の行動を順番に話してもらった。朝は駅前の喫茶店でコーヒーを飲みながら、ゆっくり新聞を読んだ。それからどこにも寄らずに郵便局へ行き、友人に小包を送った。帰りに本屋に寄って、表紙の絵が気に入った写真集を一冊買った。最後に公園のベンチでしばらく休んでから、家に戻ったそうだ。",zh:"葵請爺爺按照順序說出今天一整天的行動。早上在車站前的咖啡店一邊喝咖啡，一邊慢慢看報紙。接著沒有去其他地方，直接到郵局寄包裹給朋友。回程順路去了書店，買了一本因為喜歡封面圖片而選的攝影集。最後在公園的長椅上休息了一會兒，才回到家。"},{ja:"「どこで眼鏡を外したか覚えてる？」と葵が聞くと、祖父は首を横に振った。ただ、郵便局では一つ困ったことがあったという。小包に貼る伝票の字が小さすぎて自分では書けず、窓口の人に頼んで代わりに書いてもらったのだそうだ。本屋では中身をほとんど見ずに選んだので、字を読む必要はなかったらしい。",zh:"葵問：「你記得在哪裡拿下眼鏡的嗎？」爺爺搖了搖頭。不過，他說在郵局遇到了一件困擾的事。要貼在包裹上的託運單字太小，他自己沒辦法填寫，只好拜託窗口人員代為填寫。在書店則是幾乎沒看內容就選了，所以好像不需要看字。"},{ja:"話を聞き終えた葵は、にっこり笑った。「おじいちゃん、眼鏡は喫茶店だと思う。新聞を読んだときは、眼鏡をかけていたはずだよね。でも、郵便局ではもう小さな字が書けなかった。途中でどこにも寄っていないんだから、新聞を読み終えて外したときに、テーブルに置いてきたんじゃないかな。本屋や公園はそのあとだから、関係ないよ。」",zh:"聽完之後，葵露出了笑容。「爺爺，我想眼鏡在咖啡店。你看報紙的時候，應該是戴著眼鏡的吧。可是到了郵局，你已經沒辦法寫小字了。你中途沒有去別的地方，所以應該是看完報紙拿下眼鏡時，把它留在桌上了吧。書店和公園都是在那之後，所以沒有關係。」"},{ja:"葵が喫茶店に電話をかけると、店員はすぐに答えた。「窓際の席に、眼鏡の忘れ物がありましたよ。」祖父は新聞を読み終えると眼鏡を外してテーブルに置き、そのまま店を出てしまったのだった。祖父は「まるで探偵だな」と感心して、葵の頭をなでた。",zh:"葵打電話到咖啡店，店員馬上回答：「靠窗的座位上，有人忘了一副眼鏡喔。」原來爺爺看完報紙後，就把眼鏡拿下來放在桌上，然後直接離開了店裡。爺爺佩服地說：「簡直像個偵探啊。」並摸了摸葵的頭。"}],vocab:[{word:"訪ねる",reading:"たずねる",meaning:"拜訪"},{word:"普段",reading:"ふだん",meaning:"平常、平時"},{word:"順番",reading:"じゅんばん",meaning:"順序"},{word:"小包",reading:"こづつみ",meaning:"包裹"},{word:"伝票",reading:"でんぴょう",meaning:"單據、託運單"},{word:"窓口",reading:"まどぐち",meaning:"窗口、櫃台"},{word:"忘れ物",reading:"わすれもの",meaning:"遺失物、忘記帶走的東西"},{word:"感心",reading:"かんしん",meaning:"佩服、讚嘆"}],questions:[{question:"祖父が郵便局で困ったことは何か。",questionZh:"爺爺在郵局遇到的困擾是什麼？",options:["伝票の字が小さすぎて、自分では書けなかった","小包が重すぎて、一人では運べなかった","窓口が混んでいて、長い時間待たされた","友人の住所を思い出せず、送れなかった"]},{question:"葵が「本屋や公園は関係ない」と考えたのはなぜか。",questionZh:"葵為什麼認為「書店和公園沒有關係」？",options:["郵便局に着いたときには、もう眼鏡を持っていなかったから","本屋と公園には、すでに電話で確認していたから","祖父が本屋と公園には行っていないと言ったから","本屋と公園は、祖父の家からとても遠いから"]},{question:"眼鏡は最終的にどこで見つかったか。",questionZh:"眼鏡最後是在哪裡找到的？",options:["喫茶店の窓際の席","郵便局の窓口","本屋の写真集の棚","公園のベンチの上"]}]},{id:"n2-r20",title:"消える片方の手袋",titleZh:"消失的單隻手套",topic:"推理",paragraphs:[{ja:"十二月に入ったころから、大学生の真一のアパートで奇妙なことが続いていた。夜、ベランダに干しておいた手袋や靴下が、朝になると片方だけなくなっているのだ。部屋は二階で、外からベランダに上がれる階段もない。真一は気味が悪くなり、「謎解き名人」と呼ばれる友人の千秋に相談した。",zh:"從進入十二月左右開始，大學生真一的公寓就接連發生奇怪的事。晚上晾在陽台的手套和襪子，到了早上就有一隻不見了。房間在二樓，也沒有能從外面爬上陽台的樓梯。真一覺得毛骨悚然，便找了人稱「解謎高手」的朋友千秋商量。"},{ja:"千秋はまず、なくなった物を確かめた。毛糸の手袋、綿の靴下、小さなハンカチ。どれも軽くて柔らかい物ばかりで、一緒に干していたジーンズや厚手のタオルは一度も消えていない。また、物がなくなるのは決まって夜の間で、昼間に干した物が消えたことはないという。",zh:"千秋首先確認了不見的東西。毛線手套、棉襪、小手帕，全都是又輕又軟的東西，一起晾著的牛仔褲和厚毛巾卻一次也沒有消失過。此外，東西總是在夜裡不見，白天晾的東西從來沒有消失過。"},{ja:"次に千秋はベランダに出てみた。隣の家の屋根がベランダのすぐそばまで迫っていて、手すりの上には小さな泥の足跡が点々と残っている。人間のものにしては小さすぎる。そのとき、隣の家の窓辺で灰色の猫がのんびりと毛づくろいをしているのが目に入った。真一によると、その猫は夜になると外へ出かけ、明け方に帰ってくるそうだ。",zh:"接著千秋走到陽台看了看。隔壁房子的屋頂一直延伸到陽台旁邊，扶手上還留著點點的小泥巴腳印。如果是人的腳印，未免也太小了。這時，千秋看見隔壁房子的窗邊，有一隻灰色的貓正悠哉地理毛。據真一說，那隻貓一到晚上就會出門，天快亮時才回來。"},{ja:"「犯人がわかったよ」と千秋は言った。「重い物は消えず、口にくわえられるほど軽い物だけがなくなっている。人間なら両方まとめて持っていくはずなのに、毎回片方だけというのも不自然だ。夜にだけ起きること、屋根からベランダへ渡れること、手すりの小さな足跡。全部、あの猫に当てはまるんだ。」",zh:"「我知道犯人是誰了。」千秋說，「重的東西沒有消失，只有輕到可以用嘴叼走的東西不見了。如果是人，應該會兩隻一起拿走，每次都只拿一隻也很不自然。只在夜裡發生、能從屋頂走到陽台、扶手上的小腳印——全部都符合那隻貓。」"},{ja:"二人が隣の家を訪ねて事情を話すと、住人の老婦人は思い当たることがあるらしく、庭の物置へ案内してくれた。中の古い毛布の上には、真一の手袋や靴下がきちんと並べられていた。猫には、気に入った物を集めてくる癖があったのだ。老婦人は何度も謝り、それ以来、夜は猫を外に出さないことにしたという。",zh:"兩人拜訪隔壁人家說明情況後，住在那裡的老太太似乎想到了什麼，便帶他們到院子的倉庫。裡面的舊毛毯上，整整齊齊地排放著真一的手套和襪子。原來那隻貓有把喜歡的東西收集回來的習性。老太太再三道歉，據說從那之後，晚上就不再讓貓出門了。"}],vocab:[{word:"奇妙",reading:"きみょう",meaning:"奇怪、奇妙"},{word:"干す",reading:"ほす",meaning:"晾、曬"},{word:"気味が悪い",reading:"きみがわるい",meaning:"令人發毛、毛骨悚然"},{word:"毛糸",reading:"けいと",meaning:"毛線"},{word:"迫る",reading:"せまる",meaning:"逼近、靠近"},{word:"手すり",reading:"てすり",meaning:"扶手、欄杆"},{word:"事情",reading:"じじょう",meaning:"情況、緣由"},{word:"癖",reading:"くせ",meaning:"習性、癖好"}],questions:[{question:"なくなった物について、本文の内容に合うものはどれか。",questionZh:"關於不見的東西，下列何者符合本文內容？",options:["どれも軽くて柔らかい物だった","どれも昼間に干していた物だった","ジーンズや厚手のタオルも含まれていた","毎回両方そろってなくなっていた"]},{question:"千秋が、犯人は人間ではないと考えた理由の一つは何か。",questionZh:"千秋認為犯人不是人的理由之一是什麼？",options:["毎回、片方だけがなくなっていたから","ベランダに大きな足跡が残っていたから","部屋の窓に鍵がかかっていたから","昼間にだけ物がなくなっていたから"]},{question:"なくなった手袋や靴下は、どこで見つかったか。",questionZh:"不見的手套和襪子是在哪裡找到的？",options:["隣の家の庭にある物置の中","真一の部屋のベッドの下","アパートの屋根の上","千秋の大学のロッカーの中"]}]}]},1909,[]);
